/* ================== CASI ==================
   Ogni opzione: t testo, ok giusta, fb spiegazione, x gravità se sbagliata (0 nessun effetto sul paziente, 1 peggiora, 2 evento critico),
   s stato del paziente dopo la scelta, dead se l'evento critico porta al decesso, end didascalia dell'esito. */
export const SKIN={normal:'#e2ad86',pale:'#e3d2c3',grey:'#c3beb4',cyan:'#aab6c6',flushed:'#ef8f78'};
export const DEATH={vit:{hr:0,sys:0,dia:0,spo2:0,rr:0,ecg:'asystole'},pat:{eyes:0,skin:'grey',sweat:0,tremor:0}};
export const CASES=[
/* ---------------------------------------------------------------- 1 */
{ id:1,diff:'Base',title:"Sudore freddo alle 21:30",area:"Endocrinologia",pt:"Sig. Marco R., 58 anni · Medicina interna, letto 7",
 intro:"Sei l'infermiere del turno serale. Alle 21:30 passi per il giro dei parametri.",
 scheda:[["Motivo del ricovero","Polmonite lobare destra, 2ª giornata di antibiotico EV."],["Anamnesi","Diabete tipo 2 da 15 anni in schema basal-bolus. Ipertensione. Insufficienza renale cronica lieve (eGFR 52)."],["Terapia","Insulina glargine 22 U alle 22. Insulina lispro 8 U ai pasti. Ramipril 5 mg."],["Stasera","Nausea. Ha mangiato circa un quarto della cena. La lispro delle 19 è stata somministrata a inizio pasto."],["Parametri alle 19","PA 132/78 · FC 82 · SpO₂ 96% in aria · FR 16 · T 37,2°C · glicemia pre-cena 156 mg/dL"]],
 base:{vit:{hr:82,sys:132,dia:78,spo2:96,rr:16,temp:37.2,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'glucose',glu:118,insulin:.6,ketones:0,kshift:0}},
 steps:[
 {tag:"Valutazione",text:"Lo trovi sveglio e agitato, con la fronte imperlata di sudore e la cute fredda. Le mani tremano. Ti chiede due volte che ore sono. FC 112, PA 146/84, SpO₂ 96%.",seq:[{d:1.2,cap:"La glicemia sta scendendo",s:{phys:{glu:70}}},{d:1.8,cap:"Sudore freddo e tremore",s:{vit:{hr:112,sys:146,dia:84},pat:{sweat:1,tremor:1,skin:'pale'},phys:{glu:50}}}],
  q:"Tenendo conto della serata (insulina rapida fatta, pasto quasi saltato, funzione renale ridotta), quale valutazione fai per prima, perché decide il tuo intervento?",
  win:"Glicemia 48 mg/dL: hai trovato la causa",
  opts:[{t:"Glicemia capillare al letto, prima di qualsiasi altra rilevazione",ok:1,fb:"Insulina rapida in circolo, pasto quasi saltato, rene che elimina l'insulina più lentamente: il quadro (sudore freddo, tremore, tachicardia, confusione) è quello di un'ipoglicemia, e la glicemia capillare la conferma in un minuto."},
   {t:"Saturazione, frequenza respiratoria e auscultazione del torace, per escludere un peggioramento della polmonite",fb:"Sono valutazioni corrette in un paziente con polmonite, ma non spiegano cute fredda, tremore e confusione dopo insulina a digiuno. Mentre ausculti, la glicemia continua a scendere e il paziente diventa soporoso.",s:{pat:{eyes:0},phys:{glu:36},vit:{hr:118}},end:"Diventa soporoso: glicemia 36"},
   {t:"Temperatura timpanica e, se supera 38°C, paracetamolo al bisogno come da prescrizione",fb:"Il paracetamolo al bisogno è prescritto per la febbre, ma qui la cute è fredda e sudata: è l'attivazione adrenergica dell'ipoglicemia. Perdi minuti preziosi.",s:{pat:{eyes:0},phys:{glu:38}},end:"Peggiora: glicemia 38"},
   {t:"Valutazione neurologica completa con GCS e pupille, da documentare prima di chiamare il medico",fb:"La GCS descrive bene la coscienza, ma non indica la causa e richiede tempo. Un dato di un minuto (la glicemia) ti avrebbe già detto cosa fare.",s:{pat:{eyes:0},phys:{glu:40}},end:"Peggiora: glicemia 40"}],
  learn:"I sintomi adrenergici (sudore, tremore, tachicardia, ansia) sono l'allarme dell'organismo. Quelli neuroglicopenici (confusione, sonnolenza, comportamento strano) indicano che il cervello sta già soffrendo."},
 {tag:"Decisione",text:"Glicemia capillare 48 mg/dL. È cosciente, risponde correttamente alle domande e deglutisce senza problemi un sorso d'acqua. Sul comodino: succo d'arancia in brick da 200 mL (circa 20 g di zuccheri), cracker integrali, cioccolato al latte, yogurt intero. Nel carrello: glucagone 1 mg e glucosio 33%.",
  q:"Qual è il trattamento più appropriato in questo momento?",
  win:"La glicemia risale",
  opts:[{t:"150 mL di succo d'arancia, cioè circa 15 g di zuccheri semplici, e nuovo controllo della glicemia dopo 15 minuti",ok:1,fb:"È la regola del 15: zuccheri semplici già sciolti, assorbiti in pochi minuti, e verifica a 15 minuti."},
   {t:"Due confezioni di cracker integrali: i carboidrati complessi mantengono la glicemia stabile più a lungo",fb:"È vero che i carboidrati complessi danno una glicemia più stabile, ed è per questo che si usano dopo, come spuntino. Per correggere un'ipoglicemia sono troppo lenti: a 15 minuti la glicemia è ancora 44.",s:{phys:{glu:44}},end:"A 15 minuti: glicemia 44"},
   {t:"Una barretta di cioccolato al latte, che contiene circa 25 g di zuccheri",fb:"Il contenuto di zuccheri è sufficiente, ma i grassi rallentano lo svuotamento gastrico e l'assorbimento. A 15 minuti la glicemia è salita solo a 54.",s:{phys:{glu:54}},end:"A 15 minuti: glicemia 54"},
   {t:"Glucagone 1 mg intramuscolo nella coscia, come previsto dal protocollo per l'ipoglicemia",fb:"Il glucagone è il farmaco giusto per l'ipoglicemia grave quando il paziente non può assumere nulla per bocca. Lui deglutisce bene, e il glucagone dà spesso nausea e vomito: in un paziente già nauseato, vomita.",s:{phys:{glu:80},pat:{sweat:1}},end:"La glicemia sale, ma vomita"},
   {t:"Glucosio 33% EV in bolo attraverso l'accesso venoso già presente",fb:"Il glucosio EV corregge rapidamente, ma richiede prescrizione e si riserva a chi non può usare la via orale. Le soluzioni concentrate sono molto irritanti per la vena: compaiono dolore e arrossamento lungo il braccio.",s:{phys:{glu:110}},end:"Sale, ma la vena si infiamma"}],
  out:{vit:{hr:98},pat:{tremor:0},phys:{glu:66}},
  learn:"Se il paziente non deglutisce in sicurezza non si dà nulla per bocca: glucagone IM o glucosio EV secondo prescrizione o protocollo."},
 {tag:"Rivalutazione",text:"Dopo 15 minuti: glicemia 66 mg/dL, la sudorazione si riduce, ti chiede di poter dormire. La colazione è alle 7:30. Alle 22 è prevista la glargine 22 U.",
  q:"Cosa fai adesso, considerando anche l'insulina basale delle 22?",
  win:"Glicemia 96: notte tranquilla",
  opts:[{t:"Ripeto 15 g di zuccheri semplici e ricontrollo dopo 15 minuti. Sopra 70 mg/dL do uno spuntino con carboidrati complessi e segnalo l'episodio al medico prima della glargine",ok:1,fb:"Sotto 70 si ripete il ciclo. Lo spuntino evita che la glicemia riscenda nella notte. La dose di basale dopo un'ipoglicemia va decisa con il medico."},
   {t:"Visto che sta meglio, gli do subito i cracker e lo lascio dormire, con glicemia di controllo al mattino",fb:"Sentirsi meglio non basta: è ancora sotto 70, e i cracker agiscono lentamente. Alle 2 di notte la glicemia è 50 e nessuno se ne accorge.",s:{phys:{glu:50},pat:{eyes:0,sweat:1}},end:"Alle 2: glicemia 50, nessuno se ne accorge"},
   {t:"Somministro la glargine delle 22 come prescritto, perché l'insulina basale non va mai saltata",fb:"Il principio è corretto, ma con 66 mg/dL e un'ipoglicemia appena avvenuta la dose va discussa con il medico. Nella notte la glicemia riscende a 52.",s:{phys:{glu:52},pat:{sweat:1}},end:"Nella notte: glicemia 52"},
   {t:"Sospendo di mia iniziativa la glargine di stasera, così evito altre ipoglicemie",fb:"Modificare la terapia insulinica è una decisione medica. E saltare la basale ha un prezzo: al mattino la glicemia è 312 mg/dL.",s:{phys:{glu:312,insulin:0}},end:"Al mattino: glicemia 312"}],
  out:{vit:{hr:84,sys:130},pat:{sweat:0,skin:'normal'},phys:{glu:96}},
  learn:"L'episodio va documentato: ora, valore, trattamento, valori successivi e comunicazione al medico."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Ripensa ai sintomi che hai osservato durante l'ipoglicemia.",
  q:"Quale di questi segni indica che il cervello stava già soffrendo per mancanza di glucosio, e non solo che l'organismo aveva dato l'allarme?",
  opts:[{t:"La confusione: chiedeva più volte l'ora e rispondeva lentamente",ok:1,fb:"È un sintomo neuroglicopenico: i neuroni ricevono troppo poco glucosio."},
   {t:"La sudorazione fredda: è causata dall'attivazione del sistema simpatico sulle ghiandole sudoripare",fb:"Descrizione corretta del meccanismo, ma proprio per questo è un sintomo adrenergico, cioè di allarme."},
   {t:"Il tremore: è dovuto all'adrenalina che agisce sui recettori β2 dei muscoli",fb:"Il meccanismo è corretto: è un sintomo adrenergico, non di danno cerebrale."},
   {t:"La tachicardia: l'adrenalina stimola i recettori β1 del cuore",fb:"Anche questa è una risposta di allarme."}],
  learn:"I betabloccanti possono mascherare tremore e tachicardia: in quei pazienti l'ipoglicemia può presentarsi direttamente con confusione."},
 {tag:"Anatomia",ana:1,kn:1,text:"Nel paziente sano, quando la glicemia scende, il pancreas libera glucagone.",
  q:"Quali cellule lo producono, e dove si trovano?",
  opts:[{t:"Cellule alfa delle isole di Langerhans, la parte endocrina del pancreas",ok:1,fb:"Il glucagone stimola il fegato a liberare glucosio dal glicogeno (glicogenolisi) e a produrne di nuovo (gluconeogenesi)."},
   {t:"Cellule beta delle isole di Langerhans, che rispondono al glucosio tramite il trasportatore GLUT2",fb:"Le beta usano davvero il GLUT2 per sentire la glicemia, ma producono insulina."},
   {t:"Cellule delta delle isole di Langerhans, che producono somatostatina",fb:"La somatostatina frena sia insulina sia glucagone. Non è il glucagone."},
   {t:"Cellule acinose del pancreas, che versano il secreto nel dotto di Wirsung",fb:"Descrizione corretta della parte esocrina, che produce enzimi digestivi."}],
  learn:"Le isole di Langerhans sono circa l'1-2% del pancreas: alfa (glucagone), beta (insulina), delta (somatostatina), PP (polipeptide pancreatico)."}
 ],
 src:["American Diabetes Association, Standards of Care in Diabetes: ipoglicemia (regola del 15)","Guyton & Hall, Fisiologia medica: pancreas endocrino"]},

/* ---------------------------------------------------------------- 2 */
{ id:2,diff:'Media',title:"Fame d'aria alle 3:00",area:"Cardiologia",pt:"Sig.ra Elena B., 76 anni · Cardiologia, letto 3",
 intro:"Alle 3:00 suona il campanello. Entri e la trovi seduta sul bordo del letto, aggrappata al materasso.",
 scheda:[["Motivo del ricovero","Scompenso cardiaco cronico riacutizzato, ricoverata da 24 ore."],["Anamnesi","Cardiopatia ipertensiva, frazione d'eiezione 55%. Fibrillazione atriale parossistica. Insufficienza renale lieve."],["Terapia","Furosemide 25 mg per os mattina e sera. Ramipril. Bisoprololo. Apixaban."],["Ieri sera","La nipote le ha portato una pizza. Ha rifiutato la furosemide serale per non doversi alzare di notte."],["Peso","+1,8 kg rispetto a due giorni fa."],["Parametri ore 3:00","PA 178/98 · FC 118 · FR 30 · SpO₂ 86% in aria · T 36,8°C"]],
 base:{vit:{hr:118,sys:178,dia:98,spo2:86,rr:30,temp:36.8,ecg:'sinus'},pat:{pose:1,skin:'pale',sweat:1,eyes:1},phys:{mode:'alveolus',fluid:.75,perfusion:1,co2:.3}},
 steps:[
 {tag:"Valutazione",kn:1,text:"È sudata, parla a frasi di due o tre parole e tossisce un espettorato schiumoso rosato. Le giugulari sono turgide anche da seduta.",
  q:"All'auscultazione del torace, quale reperto conferma l'origine cardiogena della sua insufficienza respiratoria?",
  opts:[{t:"Crepitii fini inspiratori a entrambe le basi, che risalgono verso i campi medi",ok:1,fb:"Indicano liquido negli alveoli bilateralmente: con giugulari turgide, sale e diuretico saltato, il quadro è quello dell'edema polmonare cardiogeno."},
   {t:"Sibili espiratori diffusi con espirazione prolungata",fb:"Sono tipici di asma e BPCO. Nell'edema possono comparire (il cosiddetto asma cardiaco), ma da soli non confermano l'origine cardiogena."},
   {t:"Murmure vescicolare abolito a destra, con iperfonesi alla percussione dello stesso lato",fb:"È il quadro del pneumotorace."},
   {t:"Soffio bronchiale e crepitii localizzati alla base destra, con aumento del fremito vocale tattile",fb:"È il quadro di un addensamento, come nella polmonite."}],
  learn:"L'espettorato schiumoso rosato è aria mescolata a liquido e globuli rossi passati dai capillari agli alveoli."},
 {tag:"Decisione",text:"Ti chiede di aiutarla a sdraiarsi perché è sfinita. Sei solo in stanza, il collega sta chiamando il medico.",physMode:{mode:'heart',stenosis:0,preload:.95,backflow:.85,contract:.6},
  q:"Come la posizioni, e con quale razionale?",
  win:"Respira meglio da seduta",
  opts:[{t:"Seduta con schienale quasi a 90°, gambe fuori dal letto e piedi appoggiati in basso: il sangue resta nelle gambe, il precarico cala e il diaframma si espande meglio",ok:1,fb:"Riducendo il ritorno venoso arriva meno sangue al cuore sinistro in difficoltà, e la pressione nei capillari polmonari scende."},
   {t:"Supina con due cuscini sotto le gambe, per farla riposare e favorire il ritorno venoso",fb:"Favorire il ritorno venoso è utile nello shock ipovolemico. Qui aumenta il sangue che arriva a un cuore già sovraccarico: l'edema peggiora.",s:{vit:{spo2:79,rr:36},pat:{pose:0},phys:{fluid:.95}},end:"L'edema peggiora: SpO₂ 79%"},
   {t:"Semiseduta a 30-45° con un cuscino sotto le ginocchia, la posizione che previene lo scivolamento e le lesioni sacrali",fb:"È una buona posizione di prevenzione nell'allettato, ma qui l'inclinazione è insufficiente e le ginocchia sollevate aumentano il ritorno venoso.",s:{vit:{spo2:83,rr:32},pat:{pose:.8},phys:{fluid:.85}},end:"Non migliora: SpO₂ 83%"},
   {t:"Trendelenburg: testa in basso e bacino in alto",fb:"Il Trendelenburg si usa in alcune procedure, come l'inserimento di un catetere venoso centrale in giugulare. Qui spinge i visceri contro il diaframma e aumenta il ritorno venoso.",x:2,s:{vit:{spo2:70,rr:40,hr:134},pat:{pose:0,skin:'cyan'},phys:{fluid:1}},end:"Insufficienza respiratoria grave"}],
  out:{pat:{pose:2},vit:{spo2:88},phys:{fluid:.65}},
  learn:"Respirare meglio da seduti si chiama ortopnea. Il numero di cuscini usati per dormire è un dato utile in anamnesi."},
 {tag:"Decisione",text:"SpO₂ 88% in aria. Non ha BPCO né altri fattori di rischio per l'ipercapnia. Il medico arriva tra circa 5 minuti.",
  q:"Come imposti l'ossigeno in attesa del medico, secondo il protocollo di reparto basato sulle linee guida BTS?",
  win:"La saturazione risale",
  opts:[{t:"Maschera semplice a 5-10 L/min, titolando per una SpO₂ di 94-98%, con monitoraggio continuo",ok:1,fb:"Senza rischio ipercapnico l'obiettivo è 94-98%. La maschera semplice permette flussi adeguati a questo livello di ipossiemia."},
   {t:"Occhialini nasali a 2 L/min, che disturbano meno e permettono di parlare e tossire",fb:"Gli occhialini sono comodi e adatti a ipossiemie lievi. A 2 L/min, con FR 30 e respirazione a bocca aperta, l'ossigeno inspirato è troppo poco.",s:{vit:{spo2:87}},end:"Resta ipossica: SpO₂ 87%"},
   {t:"Maschera Venturi al 28% con obiettivo 88-92%, per prudenza in una paziente anziana",fb:"La Venturi con obiettivo 88-92% è corretta per chi rischia l'ipercapnia, come nella BPCO. L'età da sola non è un motivo: la paziente resta troppo ipossica.",s:{vit:{spo2:89}},end:"Resta a 89%"},
   {t:"Attendo il medico per la prescrizione: l'ossigeno è un farmaco e va prescritto",fb:"È vero che l'ossigeno è un farmaco, ma nelle emergenze si avvia secondo protocollo e si fa prescrivere subito dopo. Nei 5 minuti di attesa la saturazione scende.",s:{vit:{spo2:82,rr:34}},end:"Scende a 82%"}],
  out:{vit:{spo2:93,rr:26}},
  learn:"Riferimento pratico: occhialini 1-4 L/min, maschera semplice 5-10 L/min, maschera con reservoir 15 L/min nei casi più gravi."},
 {tag:"Rivalutazione",text:"Il medico prescrive furosemide 40 mg EV. Dopo 2 ore: diuresi 1200 mL, FR 20, SpO₂ 95% con 2 L/min, PA 132/80. Al monitor ogni tanto compare un battito anticipato.",
  q:"Quale esame di laboratorio è più importante seguire nelle prossime ore, e perché?",
  win:"K⁺ 3,3: reintegrato in tempo",
  opts:[{t:"Potassiemia: i diuretici dell'ansa ne fanno perdere molto con le urine, e l'ipokaliemia favorisce le aritmie",ok:1,fb:"Con 1200 mL in 2 ore e battiti anticipati al monitor, il potassio è la priorità."},
   {t:"Sodiemia: la furosemide può causare iponatriemia, che dà confusione e convulsioni",fb:"È vero che può, ed è un esame che si controlla. Ma il rischio più immediato, con battiti anticipati al monitor, è aritmico: il potassio. Dopo 6 ore il K⁺ è 2,9 e compaiono salve di extrasistoli.",s:{vit:{ecg:'af',hr:112}},end:"K⁺ 2,9: aritmia"},
   {t:"Troponina: per capire se un infarto ha scatenato lo scompenso",fb:"Aiuta a cercare la causa ed è spesso richiesta, ma non sorveglia l'effetto del diuretico. Dopo 6 ore il K⁺ è 2,9.",s:{vit:{ecg:'af',hr:110}},end:"K⁺ 2,9: aritmia"},
   {t:"Emocromo: un'anemia può peggiorare lo scompenso",fb:"È vero, ma non è il rischio legato alla diuresi forzata. Dopo 6 ore il K⁺ è 2,9.",s:{vit:{ecg:'af',hr:110}},end:"K⁺ 2,9: aritmia"}],
  out:{vit:{spo2:96,rr:18,hr:90,sys:136,dia:80},pat:{sweat:0,skin:'normal'},phys:{fluid:.15}},
  learn:"Dopo il diuretico: bilancio idrico, PA, creatinina e potassio, peso giornaliero alla stessa ora e con la stessa bilancia. All'educazione alla dimissione: sale e aderenza al diuretico."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Torniamo al momento dell'edema.",physMode:{mode:'alveolus',fluid:.7,perfusion:1,co2:.3},
  q:"Quale meccanismo spiega l'edema polmonare di questa paziente?",
  opts:[{t:"Aumento della pressione idrostatica nei capillari polmonari, trasmessa all'indietro dall'atrio sinistro",ok:1,fb:"Sale, diuretico saltato e cuore rigido: la pressione risale in atrio sinistro, vene e capillari polmonari, e il liquido filtra negli alveoli."},
   {t:"Riduzione della pressione oncotica plasmatica per ipoalbuminemia",fb:"È un meccanismo reale di edema (ad esempio nella cirrosi o nella sindrome nefrosica), ma lento e diffuso."},
   {t:"Aumento della permeabilità della membrana alveolo-capillare per danno infiammatorio",fb:"È il meccanismo dell'edema non cardiogeno, come nella ARDS."},
   {t:"Ridotto drenaggio linfatico del polmone",fb:"I linfatici drenano il liquido in eccesso, ma non sono la causa di un edema acuto come questo."}],
  learn:"Forze di Starling: la pressione idrostatica spinge il liquido fuori dal capillare, quella oncotica (soprattutto l'albumina) lo trattiene."},
 {tag:"Anatomia",ana:1,kn:1,text:"La furosemide agisce in un punto preciso del nefrone.",physMode:{mode:'heart',stenosis:0,preload:.55,backflow:.1,contract:.6},
  q:"Dove agisce, e su quale trasportatore?",
  opts:[{t:"Tratto ascendente spesso dell'ansa di Henle, sul cotrasportatore Na⁺-K⁺-2Cl⁻",ok:1,fb:"Lì si riassorbe circa il 25% del sodio filtrato: per questo i diuretici dell'ansa sono i più potenti."},
   {t:"Tubulo contorto distale, sul cotrasportatore Na⁺-Cl⁻",fb:"Descrizione corretta, ma è la sede dei tiazidici."},
   {t:"Dotto collettore, sui canali del sodio regolati dall'aldosterone",fb:"Descrizione corretta: è la sede dello spironolattone e dei risparmiatori di potassio."},
   {t:"Tubulo contorto prossimale, sull'anidrasi carbonica",fb:"È la sede dell'acetazolamide."}],
  learn:"Lo spironolattone, usato nello scompenso, trattiene potassio: con la furosemide i due effetti in parte si bilanciano."}
 ],
 src:["ESC 2021 Guidelines for heart failure (aggiornamento 2023): scompenso acuto","British Thoracic Society, Guideline for oxygen use in adults (2017)"]},

/* ---------------------------------------------------------------- 3 */
{ id:3,diff:'Media',title:"Troppo ossigeno",area:"Pneumologia",pt:"Sig. Giorgio T., 71 anni · Pneumologia, letto 9",
 intro:"Arriva dal pronto soccorso alle 18. Respira a labbra socchiuse, usa i muscoli del collo per inspirare.",
 scheda:[["Motivo del ricovero","Riacutizzazione di BPCO grave, espettorato purulento da 3 giorni."],["Anamnesi","Ex fumatore (50 pacchi/anno). Due ricoveri per insufficienza respiratoria ipercapnica, l'ultimo con ventilazione non invasiva. Ipertensione."],["Terapia","Tiotropio/olodaterolo inalatorio. Salbutamolo al bisogno. Nessun ossigeno a domicilio."],["EGA in PS (in aria)","pH 7,36 · PaCO₂ 52 mmHg · PaO₂ 50 mmHg · HCO₃⁻ 30 mmol/L"],["Parametri","SpO₂ 84% · FR 26 · FC 104 · PA 146/86 · T 37,6°C"]],
 base:{vit:{hr:104,sys:146,dia:86,spo2:84,rr:26,temp:37.6,ecg:'sinus'},pat:{pose:2,skin:'cyan',eyes:1},phys:{mode:'alveolus',fluid:0,perfusion:.8,co2:.55}},
 steps:[
 {tag:"Decisione",text:"Il medico ti chiede di avviare l'ossigeno e di scrivere l'obiettivo di saturazione in terapia.",
  q:"Guardando l'emogasanalisi, quale obiettivo è corretto, e quale dato lo giustifica?",
  win:"Saturazione 90%, CO₂ stabile",
  opts:[{t:"88-92%: il bicarbonato alto (30) indica che la CO₂ è alta da tempo e il rene l'ha compensata, quindi è a rischio di ritenzione",ok:1,fb:"pH quasi normale con PaCO₂ e bicarbonato alti: è un'ipercapnia cronica compensata. Questo paziente è a rischio."},
   {t:"94-98%, perché è l'obiettivo standard della maggior parte dei pazienti adulti",fb:"È lo standard per chi non ha rischio di ipercapnia. Qui la CO₂ sale.",s:{phys:{co2:.8},vit:{spo2:96,rr:20},pat:{skin:'flushed'}},end:"La CO₂ sale"},
   {t:"Almeno 96%, perché una PaO₂ di 50 mmHg è un'insufficienza respiratoria grave",fb:"PaO₂ 50 è davvero un'ipossiemia grave, ma puntare alla saturazione piena in un ipercapnico cronico fa salire la CO₂.",s:{phys:{co2:.85},vit:{spo2:98,rr:18},pat:{skin:'flushed'}},end:"La CO₂ sale"},
   {t:"85-88%, per ridurre al minimo il rischio di ipercapnia",fb:"Sotto 88% gli organi rischiano l'ipossia: il cuore accelera e compaiono aritmie.",s:{vit:{spo2:86,hr:118}},end:"Resta ipossico"}],
  learn:"pH 7,36 con PaCO₂ 52 e HCO₃⁻ 30: acidosi respiratoria cronica compensata dal rene."},
 {tag:"Decisione",text:"Devi scegliere il dispositivo.",
  q:"Quale ti permette di somministrare una percentuale di ossigeno precisa e costante, anche se il paziente cambia il modo di respirare?",
  win:"FiO₂ stabile",
  opts:[{t:"Maschera Venturi al 24% o 28%, con il flusso indicato sull'ugello",ok:1,fb:"La Venturi mescola aria e ossigeno in proporzione fissa: la FiO₂ resta stabile anche con FR alta."},
   {t:"Occhialini nasali a 4 L/min",fb:"Gli occhialini vanno bene a stabilizzazione avvenuta, ma la FiO₂ reale varia molto con la frequenza respiratoria. Ora il paziente riceve più ossigeno del previsto.",s:{phys:{co2:.7},vit:{spo2:95}},end:"FiO₂ imprevedibile"},
   {t:"Maschera semplice a 6 L/min",fb:"La maschera semplice dà una FiO₂ variabile e sotto i 5 L/min si rischia di rirespirare CO₂.",s:{phys:{co2:.72},vit:{spo2:95}},end:"La CO₂ sale"},
   {t:"Maschera con reservoir a 15 L/min",fb:"Il reservoir si usa nelle ipossiemie critiche senza rischio di ipercapnia, ad esempio nel trauma. Qui la CO₂ sale rapidamente.",s:{phys:{co2:.9},vit:{spo2:99,rr:14},pat:{eyes:0}},end:"La CO₂ sale rapidamente"}],
  out:{vit:{spo2:90}},
  learn:"Gli occhialini a basso flusso (1-2 L/min) si usano spesso dopo la stabilizzazione."},
 {tag:"Decisione",text:"Rientri dalla pausa.",seq:[{d:1.4,cap:"Un collega ha messo il reservoir a 15 L/min",s:{vit:{spo2:99},pat:{skin:'flushed'}}},{d:2,cap:"40 minuti dopo: sonnolento",s:{vit:{rr:10,hr:112},pat:{eyes:0,tremor:1},phys:{co2:.95}}}],
  q:"SpO₂ 99%, FR 10. Apre gli occhi solo se lo chiami a voce alta. Mani con tremore a scatti, cute calda e arrossata, polso pieno. Cosa fai?",
  win:"Si risveglia, la CO₂ scende",
  opts:[{t:"Sostituisco il reservoir con la Venturi titolando a 88-92%, lo stimolo per tenerlo sveglio, avviso subito il medico e preparo il materiale per l'emogasanalisi",ok:1,fb:"Sonnolenza, flapping tremor, cute calda e polso pieno sono segni di ipercapnia. Si riduce l'ossigeno gradualmente, non si toglie."},
   {t:"Rimuovo del tutto l'ossigeno per far scendere subito la CO₂",fb:"Togliere tutto di colpo fa crollare la saturazione, anche sotto il valore di partenza, perché la CO₂ alta occupa spazio negli alveoli.",x:2,s:{vit:{spo2:70,hr:132},pat:{skin:'cyan'}},end:"Ipossiemia grave: SpO₂ 70%"},
   {t:"Lo lascio riposare con il reservoir: la saturazione è ottima, ricontrollo tra un'ora",fb:"La saturazione è ottima, ma non dice nulla sulla CO₂. Continua a salire fino alla narcosi e all'arresto respiratorio.",x:2,dead:1,s:{vit:{rr:4,hr:48},phys:{co2:1}},end:"Arresto respiratorio da narcosi carbonica"},
   {t:"Abbasso lo schienale e lo metto supino, così riposa e riduce il consumo di ossigeno",fb:"Da supino il diaframma è spinto in alto dai visceri e la ventilazione si riduce ancora.",s:{pat:{pose:0},vit:{rr:8},phys:{co2:1}},end:"Respira ancora meno"}],
  out:{vit:{spo2:90,rr:20,hr:100},pat:{eyes:1,tremor:0,skin:'normal',pose:2},phys:{co2:.6}},
  learn:"Se l'emogasanalisi mostra acidosi respiratoria (pH sotto 7,35 con CO₂ alta), il medico valuta la ventilazione non invasiva."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Perché l'ossigeno ad alto flusso ha fatto salire la CO₂?",
  q:"Qual è il meccanismo principale?",
  opts:[{t:"Peggiora il rapporto ventilazione/perfusione annullando la vasocostrizione ipossica, e per effetto Haldane l'emoglobina ossigenata rilascia CO₂",ok:1,fb:"Il sangue torna verso alveoli poco ventilati e l'emoglobina trasporta meno CO₂."},
   {t:"Il paziente perde lo stimolo ipossico e smette di respirare",fb:"Lo stimolo ipossico conta, ma gli studi mostrano che la ventilazione cala poco. Il meccanismo principale è V/Q con l'effetto Haldane."},
   {t:"L'ossigeno aumenta il metabolismo cellulare e quindi la produzione di CO₂",fb:"La produzione di CO₂ non cambia in modo significativo."},
   {t:"L'ossigeno provoca broncocostrizione riflessa",fb:"L'ossigeno non chiude i bronchi."}],
  learn:"Vasocostrizione polmonare ipossica: i vasi si chiudono dove l'alveolo ha poco ossigeno, così il sangue va dove la ventilazione è buona."},
 {tag:"Anatomia",ana:1,kn:1,text:"Il respiro è regolato da chemocettori centrali e periferici.",
  q:"Dove sono i chemocettori centrali, sensibili a CO₂ e pH?",
  opts:[{t:"Sulla superficie ventrale del bulbo, a contatto con il liquor",ok:1,fb:"La CO₂ attraversa la barriera ematoencefalica e abbassa il pH del liquor: questi recettori lo rilevano."},
   {t:"Nei glomi carotidei, alla biforcazione della carotide comune",fb:"Descrizione corretta della sede, ma sono chemocettori periferici, sensibili soprattutto al calo di O₂."},
   {t:"Nei glomi aortici, sull'arco dell'aorta",fb:"Anche questi sono periferici."},
   {t:"Nel complesso pre-Bötzinger del bulbo",fb:"Lì nasce il ritmo respiratorio, ma non sono i chemocettori."}],
  learn:"Nella BPCO cronica i chemocettori centrali si adattano a una CO₂ più alta."}
 ],
 src:["British Thoracic Society, Guideline for oxygen use in adults in healthcare and emergency settings (2017)","GOLD Report 2025: gestione delle riacutizzazioni"]},

/* ---------------------------------------------------------------- 4 */
{ id:4,diff:'Media',title:"Sonno troppo profondo",area:"Chirurgia",pt:"Sig.ra Anna V., 64 anni · Ortopedia, letto 21",
 intro:"Giro delle 22. La stanza è silenziosa, la paziente russa rumorosamente.",
 scheda:[["Intervento","Protesi totale d'anca destra ieri, in anestesia spinale con sedazione."],["Anamnesi","Obesità (BMI 34). Apnee ostruttive del sonno: a casa usa la CPAP, che non ha portato in ospedale."],["Analgesia","PCA di morfina: bolo 1 mg, intervallo minimo 8 minuti. Paracetamolo 1 g ogni 8 ore."],["Pomeriggio","Dolore 8/10, 14 boli in 4 ore. Alle 20 dolore 3/10."],["Parametri alle 20","FR 13 · SpO₂ 94% in aria · FC 66 · PA 114/68 · sedazione: sonnolenta ma risvegliabile"]],
 base:{vit:{hr:66,sys:114,dia:68,spo2:94,rr:13,temp:37.1,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'brainstem',opioid:.3,naloxone:0}},
 steps:[
 {tag:"Decisione",text:"Il russamento si interrompe con pause lunghe.",seq:[{d:1.4,cap:"Gli oppioidi deprimono i centri respiratori",s:{phys:{opioid:.75}}},{d:2,cap:"Pause respiratorie di 10-15 secondi",s:{vit:{rr:7,spo2:86,hr:58},pat:{eyes:0,skin:'grey'},phys:{opioid:.95}}}],
  q:"La chiami per nome: non apre gli occhi. FR 7 con pause di 10-15 secondi, SpO₂ 86%, pupille puntiformi. Qual è la sequenza corretta di azioni immediate?",
  win:"Respira di nuovo: FR 10",
  opts:[{t:"Stimolo verbale e tattile deciso, apertura delle vie aeree con iperestensione del capo e sollevamento del mento, ossigeno, sospensione della PCA e chiamata di aiuto",ok:1,fb:"Stimolare e aprire le vie aeree spesso fa riprendere il respiro mentre si prepara l'antidoto. L'OSAS rende l'ostruzione più probabile."},
   {t:"Chiamo il medico e attendo al letto la prescrizione di naloxone, senza modificare la PCA",fb:"Chiamare è giusto, ma vie aeree, stimolazione e sospensione della PCA vanno fatte subito. Mentre aspetti, la FR scende a 5.",s:{vit:{rr:5,spo2:80,hr:52}},end:"FR 5, SpO₂ 80%"},
   {t:"Riduco il bolo della PCA da 1 a 0,5 mg e ricontrollo tra 30 minuti",fb:"Ridurre il bolo è un aggiustamento utile per il futuro, ma con FR 7 e sedazione profonda la PCA va sospesa e la paziente trattata ora.",s:{vit:{rr:5,spo2:78,hr:50}},end:"FR 5, SpO₂ 78%"},
   {t:"La lascio riposare: dopo un pomeriggio di dolore forte finalmente dorme, e la sedazione è attesa con la morfina",fb:"Un po' di sonnolenza è attesa, ma una paziente che non si sveglia alla voce, con FR 7 e OSAS, è in depressione respiratoria.",x:2,dead:1,s:{vit:{rr:2,spo2:60,hr:40}},end:"Arresto respiratorio"}],
  out:{vit:{rr:10,spo2:90,hr:62}},
  learn:"La sedazione precede la depressione respiratoria: con gli oppioidi si valuta sempre una scala di sedazione (ad esempio POSS) insieme alla FR."},
 {tag:"Decisione",text:"Il medico prescrive naloxone 0,4 mg diluito in 10 mL di fisiologica, cioè 40 microgrammi per mL. La paziente risponde solo al dolore.",
  q:"Come lo somministri?",
  win:"Sveglia, respira bene, dolore gestibile",
  opts:[{t:"Boli EV di 1-2 mL (40-80 microgrammi) ogni 2-3 minuti, valutando FR e sedazione dopo ogni bolo, fino a FR di almeno 10 e risveglio alla voce",ok:1,fb:"L'obiettivo è far respirare la paziente senza annullare tutta l'analgesia."},
   {t:"Tutti i 10 mL in bolo rapido EV, per invertire subito la depressione respiratoria",fb:"La dose totale è corretta per un'overdose fuori dall'ospedale, ma un'inversione brusca dopo chirurgia scatena dolore violento, agitazione, ipertensione e tachicardia.",s:{vit:{rr:28,hr:142,sys:192,dia:104,spo2:96},pat:{eyes:1,sweat:1,tremor:1},phys:{opioid:.1,naloxone:1}},end:"Risveglio brusco: dolore 10/10, PA 192"},
   {t:"0,4 mg intramuscolo nel deltoide, poi ricontrollo tra 30 minuti",fb:"La via IM è usata quando non c'è un accesso venoso, ma agisce più lentamente e non si può titolare. Ha un accesso EV: in 30 minuti resta in ipoventilazione.",s:{vit:{rr:8,spo2:87}},end:"Migliora poco e lentamente"},
   {t:"Boli titolati EV fino al risveglio, poi riavvio la PCA con la stessa impostazione per non lasciarla con dolore",fb:"La titolazione è corretta, ma riavviare la PCA invariata ripropone la stessa causa. La prescrizione analgesica va rivista.",s:{vit:{rr:7,spo2:86},pat:{eyes:0},phys:{opioid:.9}},end:"Dopo un'ora: di nuovo FR 7"}],
  out:{vit:{rr:14,spo2:95,hr:72},pat:{eyes:1,skin:'normal'},phys:{opioid:.35,naloxone:.85}},
  learn:"Dopo il naloxone il dolore va rivalutato: serve analgesia, con dosi o farmaci diversi."},
 {tag:"Rivalutazione",text:"Dopo 30 minuti: FR 14, sveglia, dolore 6/10, SpO₂ 95%.",
  q:"Quale piano di sorveglianza è corretto per le ore successive?",
  win:"Notte sicura",
  opts:[{t:"FR, sedazione e SpO₂ ogni 15 minuti nella prima ora e poi frequentemente per alcune ore, perché il naloxone dura meno della morfina; analgesia rivista dal medico e CPAP fatta portare dai familiari",ok:1,fb:"Il naloxone dura in genere 30-90 minuti: quando finisce, la morfina può tornare a deprimere il respiro."},
   {t:"Ricontrollo al giro delle 6: ora è sveglia e respira bene",fb:"Quando l'effetto del naloxone finisce, la depressione respiratoria ritorna senza che nessuno se ne accorga.",x:2,dead:1,s:{vit:{rr:4,spo2:70},pat:{eyes:0},phys:{opioid:.95,naloxone:0}},end:"Ri-narcotizzazione notturna"},
   {t:"Saturimetro continuo con allarme sotto 90%, senza altri controlli",fb:"Il saturimetro continuo è utile, ma con ossigeno la SpO₂ può restare normale mentre la CO₂ sale: serve anche la valutazione di FR e sedazione.",s:{vit:{rr:8,spo2:93},pat:{eyes:0},phys:{opioid:.8}},end:"SpO₂ normale, ma FR 8"},
   {t:"Controlli ogni 15 minuti per un'ora, poi ripresa della PCA con la stessa impostazione",fb:"La prima parte è corretta. Ma un'ora è poco e la PCA invariata ripropone il problema.",s:{vit:{rr:7},pat:{eyes:0},phys:{opioid:.9}},end:"Alle 2: di nuovo FR 7"}],
  out:{vit:{rr:14,spo2:96},phys:{opioid:.3,naloxone:.5}},
  learn:"Fattori di rischio per depressione respiratoria da oppioidi: OSAS, obesità, età avanzata, insufficienza renale, altri sedativi, prime 24 ore di terapia."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Il naloxone ha funzionato in pochi minuti.",
  q:"Come agisce il naloxone?",
  opts:[{t:"È un antagonista competitivo dei recettori μ: li occupa senza attivarli e sposta la morfina",ok:1,fb:"Per questo l'effetto dipende dalla dose e dura finché il naloxone resta in circolo."},
   {t:"Accelera il metabolismo epatico della morfina",fb:"Non modifica il metabolismo della morfina."},
   {t:"È un agonista parziale dei recettori μ, come la buprenorfina",fb:"La buprenorfina è davvero un agonista parziale, ma il naloxone è un antagonista puro."},
   {t:"Stimola direttamente i centri respiratori, come il doxapram",fb:"Il doxapram è uno stimolante respiratorio. Il naloxone agisce sui recettori degli oppioidi."}],
  learn:"La morfina riduce la risposta dei centri respiratori alla CO₂: la CO₂ sale ma la paziente non aumenta la ventilazione."},
 {tag:"Anatomia",ana:1,kn:1,text:"I recettori μ che rallentano il respiro sono in una zona precisa.",
  q:"Dove nasce il ritmo respiratorio automatico?",
  opts:[{t:"Nel bulbo, nel complesso pre-Bötzinger, con modulazione dal ponte",ok:1,fb:"È lì che gli oppioidi deprimono il respiro."},
   {t:"Nella corteccia motoria primaria",fb:"Controlla il respiro volontario (parlare, trattenere il fiato), non il ritmo automatico."},
   {t:"Nei motoneuroni del midollo cervicale C3-C5",fb:"Da lì partono i nervi frenici per il diaframma, ma il ritmo nasce più in alto."},
   {t:"Nel cervelletto",fb:"Il cervelletto coordina il movimento."}],
  learn:"Una lesione del midollo sopra C3 abolisce la respirazione spontanea, perché interrompe i frenici."}
 ],
 src:["Pasero Opioid-Induced Sedation Scale (POSS)","Resuscitation Council UK: gestione dell'overdose da oppioidi","Foglietto illustrativo naloxone (AIFA)"]},

/* ---------------------------------------------------------------- 5 */
{ id:5,diff:'Media',title:"Cinque minuti dopo l'antibiotico",area:"Emergenza",pt:"Sig. Luca M., 35 anni, 78 kg · Medicina d'urgenza, letto 2",
 intro:"Hai appena avviato la prima dose di antibiotico EV e sei uscito dalla stanza.",
 scheda:[["Motivo del ricovero","Cellulite della gamba sinistra con febbre."],["Anamnesi","Asma lieve, usa il salbutamolo al bisogno. Nessuna allergia nota in cartella. Da bambino ricorda un'eruzione cutanea con uno sciroppo antibiotico, mai indagata."],["Terapia in corso","Amoxicillina-clavulanato 2,2 g EV, prima dose."],["Parametri pre-infusione","PA 124/76 · FC 84 · SpO₂ 98% · FR 15 · T 37,8°C"]],
 base:{vit:{hr:84,sys:124,dia:76,spo2:98,rr:15,temp:37.8,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'vessel',dilation:.25,leak:0,bacteria:0,hemolysis:0,histamine:0}},
 steps:[
 {tag:"Decisione",text:"Dopo 5 minuti suona il campanello.",seq:[{d:1.3,cap:"I mastociti liberano istamina",s:{phys:{histamine:.9,dilation:.6}}},{d:2,cap:"Vasi dilatati, liquido nei tessuti",s:{vit:{hr:128,sys:82,dia:44,spo2:91,rr:28},pat:{hives:1,skin:'flushed',sweat:1},phys:{dilation:.95,leak:.85}}}],
  q:"Orticaria diffusa, labbra e lingua gonfie, sibili, voce rauca. PA 82/44, FC 128, SpO₂ 91%. Dice di sentirsi morire. Qual è la prima azione corretta?",
  win:"L'adrenalina agisce",
  opts:[{t:"Fermo l'infusione, chiamo il team d'emergenza e si somministra adrenalina 0,5 mg IM (0,5 mL della soluzione 1 mg/mL) nella coscia anterolaterale",ok:1,fb:"È anafilassi: vie aeree, respiro e circolo sono coinvolti. L'adrenalina IM è il farmaco salvavita."},
   {t:"Fermo l'infusione e si somministra adrenalina 0,5 mg IM nel deltoide",fb:"Dose corretta, sede meno indicata: nel deltoide l'assorbimento è più lento e meno affidabile. Il miglioramento tarda.",s:{vit:{hr:122,sys:86,spo2:91}},end:"Migliora poco e lentamente"},
   {t:"Fermo l'infusione e si somministra adrenalina 1 mg EV in bolo",fb:"1 mg EV è la dose dell'arresto cardiaco. In un paziente con polso può provocare aritmie ventricolari e infarto. L'adrenalina EV nell'anafilassi si usa solo in infusione titolata, da esperti.",x:2,dead:1,s:{vit:{hr:190,sys:230,dia:130,ecg:'vf'}},end:"Fibrillazione ventricolare"},
   {t:"Fermo l'infusione e si somministrano clorfenamina 10 mg EV e idrocortisone 200 mg EV",fb:"Sono farmaci che si usano nell'anafilassi, ma come seconda linea: non trattano lo shock né l'edema delle vie aeree. Senza adrenalina il quadro precipita.",x:2,dead:1,s:{vit:{sys:58,dia:30,spo2:78,hr:146},pat:{skin:'cyan'}},end:"Arresto cardiaco da shock anafilattico"},
   {t:"Fermo l'infusione e somministro salbutamolo spray, 4 puff con distanziatore, come per la sua asma",fb:"Il salbutamolo può aiutare il broncospasmo, ma non tratta l'ipotensione né l'edema delle labbra e della lingua.",s:{vit:{sys:72,dia:38,spo2:88}},end:"PA 72/38"}],
  out:{vit:{hr:112,sys:94,dia:56,spo2:93,rr:24},phys:{dilation:.7,leak:.5,histamine:.6}},
  learn:"Coscia anterolaterale (vasto laterale): l'assorbimento intramuscolo è più rapido e affidabile che nel deltoide o nel sottocute."},
 {tag:"Decisione",text:"L'adrenalina è stata fatta. Il paziente cerca di alzarsi per andare alla finestra.",
  q:"Come lo posizioni, e perché?",
  win:"La pressione tiene",
  opts:[{t:"Supino con le gambe sollevate; se respira con fatica, seduto con le gambe distese sul letto",ok:1,fb:"Con i vasi dilatati il sangue ristagna in periferia: sdraiato, il sangue torna al cuore."},
   {t:"Seduto sul bordo del letto con le gambe giù, che è la posizione migliore per respirare",fb:"È davvero la posizione che aiuta il respiro nell'edema polmonare. Qui però le gambe giù trattengono sangue e riducono il ritorno venoso.",s:{vit:{sys:70,dia:36,hr:140},pat:{pose:2}},end:"PA 70/36"},
   {t:"Lo accompagno in piedi alla finestra, così si calma e respira aria fresca",fb:"Passare in piedi può svuotare il cuore: è descritto come causa di arresto nell'anafilassi.",x:2,dead:1,s:{vit:{sys:40,dia:20,hr:150},pat:{pose:2}},end:"Arresto cardiaco in posizione eretta"},
   {t:"Posizione laterale di sicurezza",fb:"Si usa per una persona incosciente che respira. Lui è cosciente e ha bisogno di sostegno al circolo.",s:{vit:{sys:80}},end:"Nessun miglioramento"}],
  out:{pat:{pose:0},vit:{sys:96,dia:58}},
  learn:"Se è incinta, la paziente va posta sul fianco sinistro, per non comprimere la vena cava."},
 {tag:"Rivalutazione",text:"Dopo 5 minuti: PA 84/50, sibili ancora presenti, labbra ancora gonfie.",
  q:"Qual è il passo successivo più appropriato?",
  win:"Seconda dose: si stabilizza",
  opts:[{t:"Ripetere l'adrenalina IM e somministrare un bolo di cristalloidi EV (500-1000 mL nell'adulto) come da prescrizione",ok:1,fb:"Se dopo 5 minuti non c'è miglioramento, l'adrenalina IM si ripete. I liquidi compensano quanto uscito dai vasi."},
   {t:"Attendere l'effetto dell'idrocortisone già somministrato",fb:"I corticosteroidi agiscono in ore, non in minuti.",s:{vit:{sys:74,dia:40,spo2:89}},end:"PA 74/40"},
   {t:"Salbutamolo nebulizzato 5 mg con ossigeno",fb:"È utile per il broncospasmo residuo, ma non tratta lo shock.",s:{vit:{sys:76,dia:42}},end:"PA 76/42"},
   {t:"Cetirizina 10 mg per bocca",fb:"Agisce lentamente e con labbra e lingua gonfie deglutire è rischioso.",s:{vit:{sys:74}},end:"PA 74"}],
  out:{vit:{hr:102,sys:108,dia:64,spo2:96,rr:20},pat:{skin:'normal',sweat:0,hives:.4},phys:{dilation:.45,leak:.25,histamine:.3}},
  learn:"Se dopo due dosi di adrenalina IM il paziente non migliora (anafilassi refrattaria), serve un'infusione di adrenalina in area critica."},
 {tag:"Fisiologia",fis:1,kn:1,text:"In pochi minuti la pressione risale e i sibili si riducono.",
  q:"Quale effetto dell'adrenalina ha ridotto il broncospasmo?",
  opts:[{t:"Stimolazione dei recettori β2 della muscolatura liscia bronchiale",ok:1,fb:"I β2 rilasciano la muscolatura dei bronchi."},
   {t:"Stimolazione dei recettori α1 dei vasi",fb:"È un effetto reale dell'adrenalina: vasocostrizione, aumento della pressione, riduzione dell'edema. Ma non dilata i bronchi."},
   {t:"Stimolazione dei recettori β1 del miocardio",fb:"È un effetto reale: aumenta forza e frequenza del cuore. Non agisce sui bronchi."},
   {t:"Blocco dei recettori H1 dell'istamina",fb:"È il meccanismo degli antistaminici."}],
  learn:"L'anafilassi è spesso mediata da IgE legate ai mastociti: al contatto con l'allergene liberano istamina, triptasi e leucotrieni."},
 {tag:"Decisione",text:"Dopo un'ora sta bene e chiede di tornare a casa.",
  q:"Cosa è corretto fare?",
  win:"Dimissione sicura il giorno dopo",
  opts:[{t:"Osservazione per diverse ore per il rischio di reazione bifasica, registrazione dell'allergia in cartella e sul braccialetto, comunicazione al paziente e al medico curante",ok:1,fb:"Una seconda reazione può comparire ore dopo. L'allergia documentata protegge il paziente in futuro."},
   {t:"Può andare a casa: i parametri sono normali da un'ora",fb:"Parametri normali non escludono una reazione bifasica. A casa, 6 ore dopo, ricompaiono orticaria e dispnea.",x:2,s:{vit:{sys:86,spo2:91,hr:124},pat:{hives:1}},end:"Reazione bifasica a casa"},
   {t:"Si riprende l'amoxicillina-clavulanato a velocità ridotta, sotto stretto controllo",fb:"Il farmaco che ha causato l'anafilassi non va più somministrato.",x:2,s:{vit:{sys:78,spo2:88,hr:136},pat:{hives:1,skin:'flushed'},phys:{histamine:.9,dilation:.9,leak:.8}},end:"Seconda anafilassi"},
   {t:"Si passa a una cefalosporina di prima generazione, che appartiene a un'altra classe",fb:"Le cefalosporine hanno una struttura simile alle penicilline e una possibile reattività crociata. La scelta spetta al medico, eventualmente dopo valutazione allergologica.",s:{pat:{hives:.6}},end:"Compare orticaria"}],
  learn:"Il medico valuta la prescrizione di adrenalina autoiniettabile e l'invio all'allergologo."}
 ],
 src:["Resuscitation Council UK, Emergency treatment of anaphylaxis (2021)","EAACI Anaphylaxis Guidelines (2021)"]},

/* ---------------------------------------------------------------- 6 */
{ id:6,diff:'Media',title:"Dieci minuti di sacca",area:"Ematologia",pt:"Sig.ra Paola Rossi, 69 anni · Ortopedia, letto 12",
 intro:"Inizi il turno alle 20. Il collega del pomeriggio ti dice di aver avviato la trasfusione della signora Rossi alle 19:50.",
 scheda:[["Motivo del ricovero","Protesi di ginocchio 2 giorni fa. Hb 7,2 g/dL, astenia, FC 92."],["Gruppo sanguigno","0 positivo. Nessuna trasfusione precedente."],["Prescrizione","1 unità di emazie concentrate in 90-120 minuti."],["Nella stessa stanza","Letto 14: sig.ra Paola Rossini, 71 anni, gruppo A positivo, anche lei con una trasfusione prescritta."],["Parametri alle 19:45","PA 118/70 · FC 92 · SpO₂ 97% · FR 16 · T 36,7°C"]],
 base:{vit:{hr:92,sys:118,dia:70,spo2:97,rr:16,temp:36.7,ecg:'sinus'},pat:{pose:1,skin:'pale',eyes:1},phys:{mode:'vessel',dilation:.3,leak:0,bacteria:0,hemolysis:0,histamine:0}},
 steps:[
 {tag:"Decisione",text:"Alle 20:00 la paziente ti chiama.",seq:[{d:1.3,cap:"Gli anticorpi attaccano i globuli rossi trasfusi",s:{phys:{hemolysis:.5}}},{d:2,cap:"I globuli rossi si rompono nei vasi",s:{vit:{temp:38.9,hr:124,sys:86,dia:50,rr:24},pat:{tremor:1,sweat:1},phys:{hemolysis:1,dilation:.7}}}],
  q:"Brividi intensi, T 38,9°C, dolore lombare e al braccio dell'accesso, senso di angoscia. PA 86/50, FC 124. Cosa fai?",
  win:"Trasfusione fermata in tempo",
  opts:[{t:"Fermo subito la trasfusione, mantengo l'accesso venoso con fisiologica attraverso un deflussore nuovo, chiamo il medico e rilevo i parametri",ok:1,fb:"Sospetta reazione emolitica acuta. Fermare subito è la cosa più importante; l'accesso serve per farmaci e liquidi."},
   {t:"Fermo la trasfusione e faccio scorrere fisiologica nello stesso deflussore per mantenere pervia la vena",fb:"Mantenere pervia la vena è corretto, ma il deflussore contiene ancora sangue incompatibile: lo spingi nella paziente.",s:{vit:{sys:78,dia:44},phys:{hemolysis:1}},end:"L'emolisi peggiora"},
   {t:"Riduco la velocità a metà e somministro paracetamolo 1 g, pensando a una reazione febbrile non emolitica",fb:"La reazione febbrile non emolitica esiste ed è frequente, ma non dà ipotensione e dolore lombare. Proseguire con sangue incompatibile porta a coagulazione intravascolare e shock.",x:2,dead:1,s:{vit:{sys:52,dia:28,hr:148,spo2:84},pat:{skin:'grey'},phys:{hemolysis:1,dilation:1}},end:"Shock e coagulazione intravascolare"},
   {t:"Fermo la trasfusione e rimuovo l'ago cannula, per evitare altro passaggio di sangue",fb:"La sacca va fermata, ma l'accesso venoso serve per liquidi e farmaci proprio ora.",s:{vit:{sys:80,dia:46}},end:"Nessun accesso venoso"}],
  out:{vit:{hr:110,sys:98,dia:58},pat:{tremor:.3},phys:{hemolysis:.5}},
  learn:"La sacca e il deflussore non si buttano: vanno inviati al centro trasfusionale con i campioni della paziente."},
 {tag:"Valutazione",text:"La trasfusione è ferma, il medico sta arrivando.",
  q:"Quale controllo fai subito al letto, perché può spiegare la reazione?",
  win:"Errore trovato: sacca della sig.ra Rossini",
  opts:[{t:"Confronto braccialetto della paziente, etichetta della sacca e modulo di assegnazione: nome, cognome, data di nascita, numero della sacca e gruppo",ok:1,fb:"Sull'etichetta c'è scritto Paola Rossini, gruppo A positivo. La sacca era destinata alla paziente del letto 14."},
   {t:"Glicemia capillare, perché i brividi possono essere segno di ipoglicemia",fb:"È un controllo rapido e innocuo, ma non spiega febbre, ipotensione e dolore lombare durante una trasfusione."},
   {t:"Controllo della scadenza e dell'integrità della sacca",fb:"È un controllo previsto prima dell'avvio, ma non è quello che spiega una reazione emolitica."},
   {t:"Chiamo il centro trasfusionale per sapere se la sacca era stata irradiata",fb:"L'irradiazione previene la malattia da trapianto contro l'ospite, una complicanza diversa e tardiva."}],
  kn:1,
  learn:"Un errore di identificazione può coinvolgere due pazienti: anche la sig.ra Rossini rischia di ricevere la sacca sbagliata. Va avvisato subito il centro trasfusionale."},
 {tag:"Rivalutazione",kn:1,text:"Nelle ore successive il medico ti chiede di sorvegliare la diuresi oraria.",
  q:"Quale aspetto delle urine conferma l'emolisi intravascolare?",
  opts:[{t:"Urine scure, rosso-brunastre, per la presenza di emoglobina libera",ok:1,fb:"L'emoglobina liberata dai globuli rossi passa nelle urine (emoglobinuria) e può danneggiare il rene."},
   {t:"Urine schiumose persistenti",fb:"Fanno pensare a proteinuria, ad esempio in una malattia glomerulare."},
   {t:"Urine torbide e maleodoranti",fb:"Fanno pensare a un'infezione urinaria."},
   {t:"Urine color arancio dopo l'avvio di rifampicina",fb:"È una colorazione reale da farmaco, non legata all'emolisi."}],
  learn:"Dopo una reazione emolitica si sorvegliano diuresi oraria, funzione renale e coagulazione."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Paziente gruppo 0, sacca gruppo A.",
  q:"Perché i globuli rossi trasfusi si sono rotti?",
  opts:[{t:"Il plasma di chi è gruppo 0 contiene anticorpi naturali anti-A e anti-B (IgM) che si legano alle emazie A e attivano il complemento",ok:1,fb:"Il complemento perfora la membrana dei globuli rossi: emolisi intravascolare."},
   {t:"Il gruppo 0 è donatore universale, quindi il problema era il fattore Rh",fb:"È vero che le emazie 0 negativo si possono dare a tutti in emergenza, ma qui il ricevente è 0 e il donatore A: gli anti-A della paziente distruggono le emazie."},
   {t:"Gli anticorpi anti-0 della sacca hanno attaccato le emazie della paziente",fb:"Non esistono anticorpi anti-0. E un'unità di emazie concentrate contiene pochissimo plasma."},
   {t:"La sacca è stata infusa troppo fredda",fb:"Sangue molto freddo infuso velocemente può dare ipotermia e aritmie, ma non questa reazione."}],
  learn:"Gli anticorpi anti-A e anti-B sono presenti fin dall'infanzia: l'incompatibilità ABO è pericolosa già alla prima trasfusione."},
 {tag:"Decisione",text:"Sei tu, il giorno dopo, a dover avviare la trasfusione della sig.ra Rossini.",
  q:"Quale procedura di identificazione è corretta?",
  win:"Trasfusione corretta e sicura",
  opts:[{t:"Al letto, con un secondo operatore: chiedo alla paziente di dirmi nome, cognome e data di nascita, e confronto con braccialetto, etichetta della sacca e modulo",ok:1,fb:"È l'identificazione attiva: la paziente dice i propri dati, non li conferma."},
   {t:"Al letto chiedo: \"Lei è la signora Rossini?\" e controllo che il numero del letto corrisponda alla richiesta",fb:"È un'identificazione passiva: una paziente confusa o assonnata può rispondere sì. E i letti si cambiano.",x:2,s:{vit:{temp:38.6,hr:118,sys:88},pat:{tremor:1},phys:{hemolysis:.8}},end:"Nuovo errore di identità"},
   {t:"In guardiola, con un collega, confronto l'etichetta della sacca con la richiesta in cartella",fb:"Il doppio controllo documentale è necessario ma non basta: l'errore nasce al letto, dove si incontrano sacca e paziente.",x:2,s:{vit:{temp:38.6,hr:118,sys:88},pat:{tremor:1},phys:{hemolysis:.8}},end:"Nuovo errore di identità"},
   {t:"Verifico scadenza, integrità e aspetto della sacca, e controllo che il gruppo coincida con quello in cartella",fb:"Sono controlli dovuti, ma se la cartella è quella di un'altra paziente non proteggono.",s:{pat:{tremor:.5}},end:"Controllo incompleto"}],
  learn:"La maggior parte delle reazioni ABO gravi nasce da errori di identificazione al prelievo o al letto, non in laboratorio."}
 ],
 src:["SHOT (Serious Hazards of Transfusion), annual report e raccomandazioni","Centro Nazionale Sangue: raccomandazioni per la prevenzione della reazione trasfusionale da incompatibilità ABO"]},

/* ---------------------------------------------------------------- 7 */
{ id:7,diff:'Media',title:"La bocca storta a colazione",area:"Neurologia",pt:"Sig. Bruno L., 74 anni · Medicina interna, letto 5",
 intro:"Alle 8:10 porti la colazione.",
 scheda:[["Motivo del ricovero","Bronchite acuta, ricoverato da 2 giorni."],["Anamnesi","Fibrillazione atriale permanente. Ipertensione. Diabete tipo 2 in metformina."],["Anticoagulante","Apixaban sospeso dal medico di base 5 giorni fa per sanguinamento gengivale."],["Consegne della notte","Alle 7:30 il collega lo ha visto parlare normalmente mentre misurava i parametri."],["Parametri alle 7:30","PA 158/92 · FC 96 irregolare · SpO₂ 96% · FR 17 · T 36,9°C"]],
 base:{vit:{hr:96,sys:158,dia:92,spo2:96,rr:17,temp:36.9,ecg:'af'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'brain',occlusion:0,penumbra:0}},
 steps:[
 {tag:"Valutazione",text:"Ti saluta, ma le parole sono confuse.",seq:[{d:1.3,cap:"Un trombo blocca l'arteria cerebrale media sinistra",s:{phys:{occlusion:.85,penumbra:.8}}},{d:1.8,cap:"La bocca cade a destra",s:{pat:{droop:1},vit:{sys:178,dia:98}}}],
  q:"Angolo destro della bocca cadente, braccio destro che cade quando gli chiedi di alzarli entrambi, eloquio confuso. Hai attivato il codice ictus. Quale esame al letto fai subito, perché può cambiare la diagnosi?",
  win:"Glicemia 132: è un ictus",
  opts:[{t:"Glicemia capillare",ok:1,fb:"Un'ipoglicemia può dare sintomi identici a un ictus, soprattutto in un diabetico. Va esclusa subito: un valore basso cambia completamente il trattamento."},
   {t:"ECG a 12 derivazioni, per documentare la fibrillazione atriale",fb:"È utile e verrà fatto, ma non esclude un simulatore dell'ictus e non deve ritardare la TC."},
   {t:"Temperatura timpanica, perché la febbre peggiora il danno ischemico",fb:"È vero che la febbre peggiora la prognosi, ma non cambia la diagnosi in questo momento."},
   {t:"Scala del dolore NRS",fb:"Non aiuta a distinguere un ictus da un suo simulatore."}],
  kn:1,
  learn:"FAST: Face (volto), Arm (braccio), Speech (linguaggio), Time (tempo). BE-FAST aggiunge Balance ed Eyes."},
 {tag:"Decisione",text:"Il neurologo al telefono ti chiede quando il paziente è stato visto bene l'ultima volta.",
  q:"Che orario comunichi?",
  win:"Dentro la finestra per la trombolisi",
  opts:[{t:"Le 7:30, quando il collega lo ha visto parlare normalmente",ok:1,fb:"Conta l'ultimo momento noto in benessere, non quello in cui hai notato i sintomi."},
   {t:"Le 8:10, quando ho trovato i sintomi",fb:"L'esordio può essere in qualsiasi momento tra 7:30 e 8:10. Comunicare un orario più tardo rischia di trattare fuori finestra.",s:{phys:{occlusion:.85}},end:"Orario sbagliato in cartella"},
   {t:"Le 22 di ieri sera, l'ultima volta che l'ho visto io",fb:"Alle 7:30 era stato visto bene: è il dato più recente. Con le 22 il neurologo esclude la trombolisi e la penombra si perde.",s:{phys:{occlusion:.9,penumbra:.1}},end:"Escluso dalla trombolisi: danno permanente"},
   {t:"Le 7:50, a metà tra i due orari",fb:"Non si stima: si usa l'ultimo momento documentato in benessere.",s:{phys:{occlusion:.85}},end:"Orario non documentato"}],
  learn:"La trombolisi EV si valuta in genere entro 4,5 ore dall'ultimo momento noto in benessere."},
 {tag:"Decisione",text:"La TC esclude un'emorragia. Prima della trombolisi la PA è 196/104.",state:{vit:{sys:196,dia:104}},
  q:"Cosa fai con questo valore?",
  win:"PA 178/96: trombolisi avviata",
  opts:[{t:"Lo comunico subito al medico: per la trombolisi la PA deve essere sotto 185/110, e sarà lui a decidere se abbassarla e di quanto",ok:1,fb:"Sopra quella soglia il rischio di emorragia cerebrale dopo la trombolisi aumenta."},
   {t:"Preparo e somministro l'antipertensivo al bisogno in terapia per portarla rapidamente a 120/80",fb:"Abbassare la pressione è a volte necessario, ma un calo brusco riduce il flusso alla penombra, il tessuto ancora salvabile.",s:{vit:{sys:118,dia:70},phys:{penumbra:.2,occlusion:.95}},end:"La penombra si perde"},
   {t:"Non lo segnalo: nell'ictus acuto una PA alta è attesa e protegge il cervello",fb:"È vero che spesso è reattiva e che non va abbassata troppo, ma prima della trombolisi c'è una soglia precisa da rispettare.",s:{phys:{occlusion:.85}},end:"Trombolisi rinviata"},
   {t:"Lo interpreto come segno di emorragia e sospendo la preparazione della trombolisi",fb:"La PA alta non distingue ischemia ed emorragia: lo fa la TC, che qui è negativa.",s:{phys:{occlusion:.9,penumbra:.2}},end:"Trombolisi persa"}],
  out:{vit:{sys:178,dia:96}},
  learn:"Dopo la trombolisi PA e valutazione neurologica si controllano molto spesso nelle prime 24 ore."},
 {tag:"Decisione",text:"La trombolisi è in corso. Il paziente ha sete e ti chiede da bere per prendere la metformina del mattino.",
  q:"Cosa fai?",
  win:"Nessuna aspirazione",
  opts:[{t:"Niente per bocca, compresi farmaci e acqua, finché non è stato fatto lo screening della deglutizione; lo segnalo al medico per la metformina",ok:1,fb:"La disfagia dopo ictus è frequente e porta a polmonite ab ingestis."},
   {t:"Gli do acqua addensata a cucchiaini, che è più sicura dei liquidi",fb:"I liquidi addensati si usano nella disfagia, ma solo secondo l'esito dello screening.",s:{vit:{spo2:91,rr:24,temp:37.8}},end:"Tosse e aspirazione"},
   {t:"Gli do la compressa con un piccolo sorso d'acqua, seduto a 90°",fb:"La posizione seduta aiuta, ma anche un sorso può essere aspirato se il riflesso è alterato.",s:{vit:{spo2:90,rr:24}},end:"Tosse e aspirazione"},
   {t:"Gli do l'acqua con la cannuccia, così controlla meglio il volume",fb:"La cannuccia non protegge dall'aspirazione, anzi può aumentarla.",s:{vit:{spo2:89,rr:26}},end:"Aspirazione"}],
  out:{phys:{occlusion:.2,penumbra:.15},vit:{sys:160,dia:90},pat:{droop:.3}},
  learn:"Nell'animazione la trombolisi ha riaperto l'arteria: la penombra è stata salvata e i sintomi si riducono."},
 {tag:"Anatomia",ana:1,kn:1,text:"Il danno è nell'emisfero sinistro.",
  q:"Perché il paziente ha anche difficoltà a parlare?",
  opts:[{t:"Nella maggior parte delle persone le aree del linguaggio (Broca e Wernicke) sono nell'emisfero sinistro, nel territorio dell'arteria cerebrale media",ok:1,fb:"Per questo un ictus dell'arteria cerebrale media sinistra dà spesso afasia oltre alla paralisi a destra."},
   {t:"Le vie motorie si incrociano nel bulbo (decussazione delle piramidi)",fb:"È vero, e spiega perché la paralisi è a destra. Non spiega l'afasia."},
   {t:"L'arteria cerebrale anteriore irrora le aree del linguaggio",fb:"L'anteriore irrora soprattutto la faccia mediale dei lobi frontali e parietali (arto inferiore)."},
   {t:"Il trombo ha colpito il cervelletto",fb:"Il cervelletto dà disturbi dell'equilibrio e della coordinazione, e un eloquio scandito (disartria), non l'afasia."}],
  learn:"La fibrillazione atriale favorisce trombi nell'auricola sinistra: per questo l'anticoagulante sospeso era un fattore di rischio importante."}
 ],
 src:["ESO (European Stroke Organisation) Guidelines on intravenous thrombolysis (2021)","AHA/ASA Guidelines for the early management of acute ischemic stroke (2019)"]},

/* ---------------------------------------------------------------- 8 */
{ id:8,diff:'Difficile',title:"Dolore quando respira",area:"Chirurgia",pt:"Sig.ra Laura D., 67 anni · Ortopedia, letto 18",
 intro:"Alle 10 la aiuti a sistemarsi nel letto dopo la fisioterapia.",
 scheda:[["Intervento","Protesi totale di ginocchio sinistro, 3ª giornata."],["Anamnesi","Obesità (BMI 31). Varici agli arti inferiori. Ipertensione."],["Profilassi","Enoxaparina 4000 UI sottocute la sera. Ieri sera l'ha rifiutata per paura delle iniezioni; non è stato segnalato."],["Mobilizzazione","Poca: si è alzata solo per la fisioterapia."],["Ieri","Ha riferito fastidio al polpaccio sinistro, attribuito all'intervento."],["Parametri alle 8","PA 128/76 · FC 88 · SpO₂ 96% · FR 17 · T 37,3°C"]],
 base:{vit:{hr:88,sys:128,dia:76,spo2:96,rr:17,temp:37.3,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'alveolus',fluid:0,perfusion:1,co2:.25}},
 steps:[
 {tag:"Decisione",text:"Improvvisamente si porta la mano al petto.",seq:[{d:1.3,cap:"Un embolo arriva nell'arteria polmonare",s:{phys:{perfusion:.15}}},{d:1.9,cap:"Dispnea improvvisa",s:{vit:{hr:122,spo2:87,rr:30,sys:112,dia:70},pat:{sweat:1,skin:'pale'}}}],
  q:"Dispnea improvvisa, dolore toracico che peggiora inspirando, è ansiosa. FC 122, SpO₂ 87%, FR 30, PA 112/70. Cosa fai?",
  win:"Stabilizzata in attesa del medico",
  opts:[{t:"La metto semiseduta, avvio ossigeno, monitoraggio continuo, chiamo urgentemente il medico e controllo che l'accesso venoso sia funzionante",ok:1,fb:"Il quadro fa sospettare un'embolia polmonare: servono valutazione medica immediata e monitoraggio."},
   {t:"Eseguo un ECG a 12 derivazioni e la rivaluto tra un'ora",fb:"L'ECG si fa e può mostrare un sovraccarico destro, ma con questi parametri non si aspetta un'ora.",s:{vit:{hr:132,spo2:84,sys:98}},end:"Peggiora: PA 98"},
   {t:"Somministro salbutamolo per aerosol, pensando a un broncospasmo",fb:"Non ci sono sibili: il problema è nei vasi, non nei bronchi. Il salbutamolo aumenta anche la frequenza cardiaca.",s:{vit:{hr:138,spo2:85}},end:"FC 138"},
   {t:"La aiuto ad alzarsi e a fare due passi, per migliorare la ventilazione e ridurre l'ansia",fb:"Mobilizzare previene la trombosi, ma con un'embolia in corso e un trombo nel polpaccio può staccare altro materiale.",x:2,dead:1,s:{vit:{hr:150,spo2:70,sys:60,dia:30},pat:{skin:'cyan'},phys:{perfusion:0}},end:"Embolia massiva: arresto cardiaco"}],
  out:{pat:{pose:1.4},vit:{spo2:92,hr:116}},
  learn:"Segni che fanno pensare all'embolia polmonare: dispnea improvvisa, tachicardia, dolore pleuritico, a volte emottisi o sincope, dopo immobilità o chirurgia."},
 {tag:"Valutazione",kn:1,text:"Il medico arriva e ti chiede cosa hai notato all'esame obiettivo.",
  q:"Quale reperto rende l'embolia polmonare più probabile delle alternative?",
  opts:[{t:"Polpaccio sinistro gonfio, caldo e dolente, con circonferenza di 3 cm maggiore del destro",ok:1,fb:"Indica una trombosi venosa profonda, la fonte più comune dell'embolo. Nel punteggio di Wells vale 3 punti."},
   {t:"Crepitii fini a entrambe le basi",fb:"Fanno pensare a edema polmonare cardiogeno."},
   {t:"Febbre 38,5°C con tosse ed espettorato giallo",fb:"Fanno pensare a una polmonite."},
   {t:"Sibili espiratori diffusi",fb:"Fanno pensare a un broncospasmo."}],
  learn:"La profilassi saltata ieri sera e non segnalata è un'informazione da comunicare subito al medico."},
 {tag:"Fisiologia",fis:1,kn:1,text:"All'auscultazione i polmoni sono puliti, eppure la saturazione è bassa.",
  q:"Perché c'è ipossiemia?",
  opts:[{t:"Una parte di polmone è ventilata ma non perfusa, e il resto riceve più sangue di quanto la ventilazione possa ossigenare: squilibrio ventilazione/perfusione",ok:1,fb:"L'aria arriva, ma il sangue non passa da lì: lo scambio diventa inefficiente."},
   {t:"Gli alveoli sono pieni di liquido e l'ossigeno non attraversa la membrana",fb:"È il meccanismo dell'edema polmonare, che darebbe crepitii."},
   {t:"I bronchi sono ristretti e l'aria non arriva agli alveoli",fb:"È il meccanismo dell'asma."},
   {t:"L'emoglobina è legata a un'altra molecola e non trasporta ossigeno",fb:"È il meccanismo dell'intossicazione da monossido di carbonio."}],
  learn:"Un'embolia estesa fa salire la pressione in arteria polmonare e sovraccarica il ventricolo destro: è la causa dello shock nell'embolia massiva."},
 {tag:"Anatomia",ana:1,kn:1,text:"Il trombo è partito dalla vena poplitea sinistra.",
  q:"Quale percorso fa per arrivare al polmone?",
  opts:[{t:"Vena femorale → vena iliaca → vena cava inferiore → atrio destro → ventricolo destro → arteria polmonare",ok:1,fb:"Il sangue venoso porta il trombo al cuore destro, che lo spinge nel circolo polmonare."},
   {t:"Vena femorale → vena iliaca → vena cava inferiore → atrio sinistro → aorta",fb:"La cava sbocca nell'atrio destro. Un passaggio diretto a sinistra avviene solo con un forame ovale pervio (embolia paradossa)."},
   {t:"Vena poplitea → vene polmonari → polmone",fb:"Le vene polmonari portano sangue dai polmoni all'atrio sinistro, nel verso opposto."},
   {t:"Vena femorale → vena cava superiore → ventricolo destro",fb:"Le vene delle gambe arrivano alla cava inferiore."}],
  learn:"Un trombo venoso si ferma nei polmoni perché i capillari polmonari sono il primo filtro che incontra."},
 {tag:"Decisione",text:"La paziente inizia l'anticoagulante. Il giorno dopo ti occupi di un'altra paziente operata di anca.",physMode:{mode:'alveolus',fluid:0,perfusion:.7,co2:.25},
  q:"Quale insieme di interventi infermieristici previene meglio la trombosi venosa?",
  win:"Nessuna trombosi",
  opts:[{t:"Mobilizzazione precoce, esercizi di flesso-estensione della caviglia, idratazione adeguata, profilassi prescritta somministrata e un eventuale rifiuto segnalato subito",ok:1,fb:"Si agisce sulla stasi, il fattore più modificabile, e si garantisce la profilassi."},
   {t:"Calze elastiche a compressione graduata a tutti gli operati, senza bisogno di misurazione",fb:"Le calze sono efficaci, ma vanno misurate e sono controindicate in alcuni casi, come l'arteriopatia periferica.",s:{phys:{perfusion:.8}},end:"Lesione da calza mal misurata"},
   {t:"Riposo a letto con gambe sollevate per i primi 7 giorni",fb:"Sollevare le gambe riduce l'edema, ma l'immobilità è il principale fattore di rischio.",x:2,s:{phys:{perfusion:.2},vit:{spo2:88,hr:120}},end:"Nuova embolia"},
   {t:"Massaggio quotidiano dei polpacci per favorire il ritorno venoso",fb:"Il massaggio non previene la trombosi ed è rischioso se un trombo è già presente.",s:{phys:{perfusion:.6}},end:"Rischio non ridotto"}],
  out:{vit:{hr:92,spo2:95,rr:18},pat:{sweat:0,skin:'normal'},phys:{perfusion:.8}},
  learn:"Triade di Virchow: stasi, danno della parete del vaso, ipercoagulabilità. La chirurgia ortopedica di anca e ginocchio le mette insieme tutte e tre."}
 ],
 src:["ESC 2019 Guidelines for acute pulmonary embolism","NICE NG89: Venous thromboembolism in over 16s, reducing the risk (aggiornato 2019)"]},

/* ---------------------------------------------------------------- 9 */
{ id:9,diff:'Difficile',title:"Febbre e confusione",area:"Infettivologia",pt:"Sig. Franco P., 80 anni, 80 kg · Medicina interna, letto 10",
 intro:"Alle 16 la figlia ti ferma in corridoio: oggi il padre non la riconosce bene.",
 scheda:[["Motivo del ricovero","Scompenso cardiaco, ricoverato da 6 giorni."],["Dispositivi","Catetere vescicale da 6 giorni, posizionato in PS per il monitoraggio della diuresi, mai rivalutato."],["Anamnesi","Diabete tipo 2, ipertrofia prostatica, lieve deterioramento cognitivo (vive con la figlia, autonomo)."],["Terapia","Furosemide, ramipril, bisoprololo, metformina."],["Parametri alle 8","PA 122/70 · FC 92 · SpO₂ 95% · FR 18 · T 37,5°C · urine torbide"]],
 base:{vit:{hr:92,sys:122,dia:70,spo2:95,rr:18,temp:37.5,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'vessel',dilation:.3,leak:0,bacteria:.2,hemolysis:0,histamine:0}},
 steps:[
 {tag:"Valutazione",kn:1,text:"Rilevi i parametri.",seq:[{d:1.3,cap:"I batteri passano nel sangue",s:{phys:{bacteria:.85}}},{d:1.9,cap:"L'infiammazione dilata i vasi",s:{vit:{temp:38.9,hr:118,sys:92,dia:50,rr:24,spo2:93},pat:{skin:'flushed',sweat:1},phys:{dilation:.85,leak:.6}}}],
  q:"T 38,9°C, FC 118, PA 92/50, FR 24, SpO₂ 93%, confuso. Tra questi dati, quale indica un danno d'organo e non solo un'infezione?",
  opts:[{t:"La confusione nuova notata dalla figlia, in un paziente che di solito la riconosce",ok:1,fb:"Un'alterazione mentale nuova è un segno di disfunzione cerebrale per ridotta perfusione e infiammazione."},
   {t:"La febbre a 38,9°C",fb:"Indica infezione e infiammazione, non di per sé un danno d'organo. Gli anziani possono avere sepsi anche senza febbre."},
   {t:"La FC di 118",fb:"È una risposta di compenso, presente anche in infezioni senza sepsi. Il betabloccante può anzi attenuarla."},
   {t:"Il catetere da 6 giorni",fb:"È il probabile punto di partenza dell'infezione e un fattore di rischio, non un segno di danno."}],
  learn:"Sepsi: disfunzione d'organo pericolosa per la vita causata da una risposta alterata dell'organismo a un'infezione (Sepsis-3)."},
 {tag:"Valutazione",kn:1,text:"In aria ambiente: FR 24, SpO₂ 93%, PA 92/50, FC 118, confusione nuova, T 38,9°C.",
  q:"Quanto vale il NEWS2 e che risposta richiede?",
  opts:[{t:"12: risposta d'emergenza, con valutazione immediata da parte di un team esperto",ok:1,fb:"FR 24 = 2, SpO₂ 93% = 2, aria = 0, PAS 92 = 2, FC 118 = 2, confusione nuova = 3, T 38,9 = 1."},
   {t:"9: risposta d'emergenza",fb:"La risposta è giusta, il conto no: probabilmente hai dato 0 alla confusione nuova, che nel NEWS2 vale 3."},
   {t:"7: risposta d'emergenza",fb:"Ricontrolla FR (21-24 = 2) e SpO₂ (92-93% = 2)."},
   {t:"5: risposta urgente entro un'ora",fb:"Hai sottostimato più voci. Rifai il conto parametro per parametro."}],
  learn:"NEWS2 5-6, o un singolo parametro a 3: risposta urgente. 7 o più: risposta d'emergenza."},
 {tag:"Decisione",text:"Il medico conferma: sospetta sepsi di origine urinaria. Ti chiede di procedere con il pacchetto della prima ora.",
  q:"Qual è la sequenza corretta?",
  win:"Antibiotico entro un'ora",
  opts:[{t:"Emocolture da due siti, urinocoltura dal punto di prelievo del catetere, lattati, antibiotico EV entro un'ora senza ritardarlo per i prelievi, liquidi in bolo come prescritto",ok:1,fb:"Le colture prima dell'antibiotico aiutano a identificare il batterio, ma non devono ritardarlo."},
   {t:"Antibiotico subito, poi emocolture alla mattina successiva quando passa il prelievista",fb:"L'antibiotico precoce è giusto, ma dopo l'antibiotico le colture possono risultare negative anche se l'infezione c'è.",s:{phys:{bacteria:.5}},end:"Colture inutilizzabili"},
   {t:"Emocolture e urinocoltura, poi attesa dell'antibiogramma per scegliere l'antibiotico giusto",fb:"L'antibiogramma richiede 24-48 ore. Nell'attesa la sepsi diventa shock.",x:2,dead:1,s:{vit:{sys:62,dia:30,hr:138},pat:{skin:'grey'},phys:{bacteria:1,dilation:1,leak:1}},end:"Shock settico"},
   {t:"Urinocoltura dalla sacca di raccolta, poi antibiotico",fb:"Il campione dalla sacca è contaminato: i batteri si moltiplicano nell'urina ferma. Si preleva dal punto dedicato, dopo disinfezione.",s:{phys:{bacteria:.6}},end:"Campione contaminato"}],
  out:{vit:{hr:106,sys:102,dia:58,temp:38.4},phys:{bacteria:.45,dilation:.6,leak:.35}},
  learn:"Con ipotensione o lattati ≥ 4 mmol/L le linee guida suggeriscono almeno 30 mL/kg di cristalloidi nelle prime 3 ore: per 80 kg sono 2400 mL."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Ritorna alla PA iniziale: 92/50 mmHg.",
  q:"Quanto vale la pressione arteriosa media, e perché conta più della sistolica?",
  opts:[{t:"Circa 64 mmHg: è la pressione media che perfonde gli organi durante tutto il ciclo cardiaco",ok:1,fb:"PAM ≈ (92 + 2 × 50) / 3 ≈ 64. Sotto 65 mmHg la perfusione degli organi è a rischio."},
   {t:"71 mmHg: la media tra sistolica e diastolica",fb:"La diastolica pesa il doppio, perché il cuore passa circa due terzi del ciclo in diastole."},
   {t:"42 mmHg: la differenza tra sistolica e diastolica",fb:"Questa è la pressione differenziale, non la media."},
   {t:"78 mmHg: la sistolica meno un sesto",fb:"Non è una formula valida."}],
  learn:"Nello shock settico l'obiettivo iniziale è una PAM di almeno 65 mmHg."},
 {tag:"Rivalutazione",text:"Dopo un'ora e 1000 mL di cristalloidi: PA 104/58, FC 104. Diuresi dell'ultima ora: 15 mL.",
  q:"Il paziente pesa 80 kg. Come interpreti la diuresi e cosa fai?",
  win:"Catetere libero, segnalato: diuresi riparte",
  opts:[{t:"È sotto 0,5 mL/kg/h (cioè 40 mL/h): controllo che il catetere non sia piegato od ostruito e lo segnalo subito al medico",ok:1,fb:"Prima si esclude un problema meccanico, poi si segnala: è un segno di perfusione renale insufficiente."},
   {t:"È accettabile per un anziano con scompenso, che tende a urinare meno",fb:"L'obiettivo minimo è 0,5 mL/kg/h anche nell'anziano.",s:{vit:{sys:90,dia:48},phys:{leak:.6}},end:"Danno renale acuto"},
   {t:"Riduco la velocità dei liquidi per non sovraccaricare il cuore scompensato",fb:"Il timore del sovraccarico è legittimo, ma la velocità dei liquidi è una decisione medica, e la diuresi bassa può indicare proprio bisogno di volume.",s:{vit:{sys:86,dia:46,hr:118}},end:"PA 86/46"},
   {t:"Annoto il dato e aspetto il bilancio delle 24 ore",fb:"Nella sepsi la diuresi oraria serve proprio a reagire in fretta.",s:{vit:{sys:88,dia:46}},end:"Nessuno reagisce"}],
  out:{vit:{sys:112,dia:64,hr:96,temp:37.9,rr:20},pat:{sweat:0,skin:'normal'},phys:{bacteria:.25,dilation:.45,leak:.2}},
  learn:"Indicatori pratici di perfusione: diuresi, stato mentale, cute, tempo di riempimento capillare, lattati."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Il paziente non ha perso sangue, eppure la pressione è crollata.",
  q:"Perché?",
  opts:[{t:"Mediatori dell'infiammazione come l'ossido nitrico dilatano i vasi e ne aumentano la permeabilità: il liquido esce nei tessuti",ok:1,fb:"Il contenitore si allarga e perde liquido: il volume efficace cala anche senza emorragia. È uno shock distributivo."},
   {t:"La febbre deprime la contrazione del cuore fino a fermarlo",fb:"Nella sepsi può esserci una disfunzione miocardica, ma all'inizio il cuore anzi accelera per compensare."},
   {t:"I batteri distruggono i globuli rossi e riducono il volume di sangue",fb:"Alcuni batteri possono causare emolisi, ma non è il meccanismo dello shock settico."},
   {t:"Il rene trattiene acqua e sodio",fb:"È il contrario di ciò che spiega l'ipotensione."}],
  learn:"Lo shock settico e quello anafilattico sono entrambi distributivi: il problema principale è nei vasi."}
 ],
 src:["Surviving Sepsis Campaign: International Guidelines 2021","Royal College of Physicians, National Early Warning Score (NEWS) 2","Singer M. et al., Sepsis-3 definitions, JAMA 2016"]},

/* ---------------------------------------------------------------- 10 */
{ id:10,diff:'Difficile',title:"Il potassio al telefono",area:"Nefrologia",pt:"Sig. Ettore G., 72 anni · Nefrologia, letto 4",
 intro:"Alle 14 il laboratorio ti chiama per un valore critico.",
 scheda:[["Motivo del ricovero","Insufficienza renale cronica in emodialisi (lunedì, mercoledì, venerdì). Ricoverato per l'accesso vascolare malfunzionante."],["Ultima dialisi","Saltata venerdì per il malfunzionamento della fistola. Oggi è lunedì."],["Terapia","Ramipril. Bisoprololo. Sostituto del sale a base di potassio, portato da casa."],["Sintomi","Debolezza alle gambe, formicolii, si sente stanco."],["Parametri alle 13","PA 150/88 · FC 64 · SpO₂ 96% · FR 16 · T 36,6°C"]],
 base:{vit:{hr:64,sys:150,dia:88,spo2:96,rr:16,temp:36.6,ecg:'sinus'},pat:{pose:1,skin:'normal',eyes:1},phys:{mode:'myocyte',k:5.0,calcium:0}},
 steps:[
 {tag:"Decisione",text:"Il laboratorio ti telefona.",seq:[{d:1.3,cap:"Il potassio extracellulare sale",s:{phys:{k:7.1}}},{d:1.8,cap:"Onde T alte e appuntite",s:{vit:{ecg:'peakedT',hr:56}}}],
  q:"K⁺ 7,1 mmol/L, con la nota \"campione lievemente emolizzato\". Al monitor vedi onde T alte e appuntite, FC 56. Cosa fai?",
  win:"Valore trattato come vero",
  opts:[{t:"Considero il valore vero: ECG a 12 derivazioni, monitoraggio continuo, chiamo subito il medico e si ripete il prelievo senza ritardare il trattamento",ok:1,fb:"L'emolisi può alzare falsamente il potassio, ma le onde T appuntite dicono che il problema è reale."},
   {t:"Lo considero falsato dall'emolisi e programmo un nuovo prelievo per domattina",fb:"L'emolisi del campione è una causa reale di falso aumento, ma qui l'ECG conferma il problema. Nella notte compare una fibrillazione ventricolare.",x:2,dead:1,s:{phys:{k:8.2},vit:{ecg:'vf',hr:220}},end:"Fibrillazione ventricolare"},
   {t:"Ripeto subito il prelievo e aspetto il risultato prima di avvisare il medico",fb:"Ripetere è corretto, ma va fatto mentre si avvisa e si monitora. Nell'attesa il QRS si allarga.",s:{phys:{k:7.6},vit:{hr:48}},end:"QRS che si allarga"},
   {t:"Gli tolgo il sostituto del sale dal comodino e lo annoto in consegna",fb:"Giusto toglierlo, ed è una causa probabile, ma ora la priorità è il cuore.",s:{phys:{k:7.4},vit:{hr:50}},end:"Il potassio sale ancora"}],
  learn:"I sostituti del sale contengono cloruro di potassio: sono pericolosi in insufficienza renale e con farmaci come il ramipril."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Il medico prescrive calcio gluconato 10%, 30 mL EV in 5-10 minuti.",
  q:"Qual è lo scopo del calcio in questa situazione?",
  opts:[{t:"Stabilizza la membrana delle cellule cardiache e riduce il rischio di aritmie, senza abbassare il potassio",ok:1,fb:"Protegge il cuore in pochi minuti, ma per poco tempo."},
   {t:"Sposta il potassio dentro le cellule",fb:"È l'effetto di insulina-glucosio e del salbutamolo."},
   {t:"Lega il potassio nell'intestino e ne favorisce l'eliminazione con le feci",fb:"È l'effetto delle resine leganti, come il patiromer."},
   {t:"Aumenta l'eliminazione renale del potassio",fb:"È l'effetto dei diuretici dell'ansa, utile solo se il rene funziona."}],
  out:{phys:{calcium:.9},vit:{hr:62}},
  learn:"Il calcio va dato in una vena di buon calibro: se stravasa può danneggiare i tessuti."},
 {tag:"Decisione",text:"Viene prescritta insulina rapida 10 U in 25 g di glucosio EV in 15 minuti. Il paziente non è diabetico, glicemia di partenza 92 mg/dL.",
  q:"Cosa sorvegli dopo l'infusione?",
  win:"Nessuna ipoglicemia",
  opts:[{t:"Glicemia capillare ripetutamente, per almeno 6 ore, e potassio dopo 1-2 ore",ok:1,fb:"Nei pazienti renali l'insulina dura di più e l'ipoglicemia può arrivare tardi. Il potassio va ricontrollato per vedere l'effetto."},
   {t:"Glicemia solo a fine infusione, quando l'effetto è massimo",fb:"L'ipoglicemia può comparire anche 2-4 ore dopo. Alle 18 il paziente è sudato e confuso.",s:{pat:{sweat:1,eyes:0}},end:"Ipoglicemia tardiva"},
   {t:"Potassio dopo 24 ore, per vedere l'effetto completo",fb:"L'effetto dell'insulina sul potassio dura poche ore: va ricontrollato molto prima.",s:{phys:{k:6.9},vit:{ecg:'peakedT'}},end:"Il potassio risale"},
   {t:"Nulla di specifico: insulina e glucosio insieme si bilanciano",fb:"Il glucosio serve proprio a limitare l'ipoglicemia, che resta però un rischio frequente.",s:{pat:{sweat:1,eyes:0}},end:"Ipoglicemia"}],
  out:{vit:{ecg:'sinus',hr:70},phys:{k:5.6,calcium:.4}},
  learn:"Spostare il K⁺: insulina-glucosio, salbutamolo. Eliminarlo: dialisi, resine leganti, diuretici. Qui la soluzione definitiva è la dialisi."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Torniamo alla cellula cardiaca.",physMode:{mode:'myocyte',k:7.1,calcium:0},
  q:"Perché un K⁺ extracellulare alto è pericoloso per il cuore?",
  opts:[{t:"Il potenziale di riposo diventa meno negativo, molti canali del sodio si inattivano e la conduzione dell'impulso rallenta",ok:1,fb:"Le cellule sono parzialmente depolarizzate e meno eccitabili."},
   {t:"Il potenziale di riposo diventa più negativo e le cellule non raggiungono la soglia",fb:"È ciò che succede nell'ipokaliemia. Con K⁺ alto il potenziale si avvicina allo zero."},
   {t:"Il potassio entra in eccesso nelle cellule e le fa contrarre troppo",fb:"La forza della contrazione dipende soprattutto dal calcio."},
   {t:"Il potassio provoca uno spasmo delle coronarie",fb:"È un problema elettrico, non di flusso coronarico."}],
  learn:"La pompa Na⁺/K⁺-ATPasi tiene il K⁺ alto dentro (circa 140 mmol/L) e basso fuori (3,5-5 mmol/L)."},
 {tag:"Valutazione",kn:1,text:"Immagina che il potassio continui a salire senza trattamento.",
  q:"Quale sequenza di alterazioni ECG ti aspetti?",
  opts:[{t:"Onde T appuntite → onde P appiattite e PR allungato → QRS larghi → onda sinusoidale → fibrillazione ventricolare o asistolia",ok:1,fb:"È la progressione classica, anche se non sempre segue quest'ordine."},
   {t:"Sopraslivellamento del tratto ST → onde Q patologiche",fb:"È l'evoluzione di un infarto."},
   {t:"Onde T appiattite → comparsa di onde U → QT apparentemente lungo",fb:"È il quadro dell'ipokaliemia."},
   {t:"QT accorciato",fb:"È tipico dell'ipercalcemia."}],
  learn:"L'ECG non è sensibile: un paziente può avere un K⁺ molto alto con ECG quasi normale."}
 ],
 src:["UK Kidney Association, Clinical Practice Guidelines: Treatment of acute hyperkalaemia in adults (2023)","Resuscitation Council UK, Advanced Life Support: alterazioni elettrolitiche"]},

/* ---------------------------------------------------------------- 11 */
{ id:11,diff:'Difficile',title:"L'alito che sa di frutta",area:"Endocrinologia",pt:"Giulia F., 19 anni, 58 kg · Medicina d'urgenza, letto 6",
 intro:"Arriva accompagnata dalla madre. È pallida e stanca, risponde lentamente.",
 scheda:[["Motivo dell'accesso","Vomito e dolore addominale da 2 giorni."],["Anamnesi","Diabete tipo 1 da 8 anni, schema basal-bolus con penne."],["Cosa è successo","Gastroenterite: mangiava poco e per paura di ipoglicemie ha smesso sia la rapida sia la basale da 36 ore."],["Esami","Glicemia 480 mg/dL · chetonemia 5,2 mmol/L · pH 7,10 · HCO₃⁻ 9 mmol/L · K⁺ 3,0 mmol/L"],["Parametri","PA 98/58 · FC 124 · FR 30 · SpO₂ 98% · T 37,4°C · mucose secche"]],
 base:{vit:{hr:124,sys:98,dia:58,spo2:98,rr:30,temp:37.4,ecg:'sinus'},pat:{pose:1,skin:'pale',eyes:1,sweat:0},phys:{mode:'glucose',glu:480,insulin:0,ketones:.9,kshift:.7}},
 steps:[
 {tag:"Valutazione",kn:1,text:"Respira in modo profondo, veloce e regolare. L'alito ha un odore dolciastro, come di frutta matura.",
  q:"Quale respiro stai osservando, e perché si presenta così?",
  opts:[{t:"Respiro di Kussmaul: elimina CO₂ per compensare un'acidosi metabolica",ok:1,fb:"I chetoni sono acidi. Respirando di più si elimina CO₂ e il pH risale un po'."},
   {t:"Respiro di Cheyne-Stokes: atti crescenti e decrescenti alternati a pause, per alterazione dei centri respiratori",fb:"La descrizione è corretta, ma il Cheyne-Stokes ha pause di apnea. Qui il respiro è regolare."},
   {t:"Tachipnea superficiale antalgica da dolore addominale",fb:"Esiste, ma il respiro di Giulia è profondo, non superficiale."},
   {t:"Iperventilazione da attacco di panico, con parestesie alle mani",fb:"L'iperventilazione d'ansia esiste e dà parestesie, ma qui c'è un'acidosi grave documentata."}],
  learn:"L'odore di frutta è l'acetone, uno dei corpi chetonici, eliminato con il respiro."},
 {tag:"Decisione",text:"Il medico imposta il protocollo per la chetoacidosi. Prima di tutto c'è una priorità.",
  q:"Qual è la prima terapia che ti aspetti di avviare?",
  win:"Il volume si ripristina",
  opts:[{t:"Fisiologica 0,9% EV in bolo (ad esempio 1000 mL in un'ora) come prescritto, con potassio controllato prima di iniziare l'insulina",ok:1,fb:"La diuresi osmotica ha causato una grande perdita di liquidi: il volume si ripristina per primo."},
   {t:"Insulina rapida 10 U sottocute subito, per bloccare la produzione di chetoni",fb:"Bloccare i chetoni è l'obiettivo, ma nella chetoacidosi l'insulina si dà in infusione EV e solo dopo il controllo del potassio. Il sottocute in una paziente disidratata è assorbito male.",s:{vit:{sys:92,hr:128}},end:"Assorbimento irregolare"},
   {t:"Bicarbonato di sodio EV per correggere il pH di 7,10",fb:"Il bicarbonato è riservato a casi selezionati con pH molto più basso, su indicazione medica. Può peggiorare l'ipokaliemia.",s:{phys:{kshift:.2},vit:{ecg:'af'}},end:"Il potassio scende"},
   {t:"Glucosata 5% EV, che reidrata senza aggiungere sodio",fb:"Con glicemia 480 si usa la fisiologica. Il glucosio si aggiunge più tardi, quando la glicemia scende sotto circa 250 mg/dL.",s:{phys:{glu:520}},end:"Glicemia 520"}],
  out:{vit:{sys:106,dia:62,hr:116}},
  learn:"Il glucosio nelle urine trascina acqua (diuresi osmotica): poliuria, sete, disidratazione. Una paziente in chetoacidosi può aver perso diversi litri."},
 {tag:"Decisione",text:"Dopo il primo litro, il potassio di controllo è ancora 3,0 mmol/L. Il medico ti chiede se è pronta l'infusione di insulina.",physMode:{mode:'glucose',glu:420,insulin:0,ketones:.8,kshift:.7},
  q:"Si può avviare l'infusione di insulina adesso?",
  win:"Potassio reintegrato, insulina avviata in sicurezza",
  opts:[{t:"No: prima si reintegra il potassio EV come prescritto, e l'insulina si avvia quando il K⁺ è almeno 3,3 mmol/L",ok:1,fb:"L'insulina sposta il K⁺ nelle cellule: partendo da 3,0 scenderebbe a livelli pericolosi per il cuore."},
   {t:"Sì: il potassio è basso ma l'acidosi è la priorità, e l'insulina la corregge",fb:"L'acidosi va corretta, ma l'insulina con K⁺ 3,0 provoca un'ipokaliemia grave e aritmie.",x:2,dead:1,s:{phys:{insulin:.8,kshift:0},vit:{ecg:'vf',hr:210}},end:"Aritmia da ipokaliemia"},
   {t:"Sì, a velocità doppia per correggere più in fretta",fb:"Raddoppiare aumenta sia l'ipokaliemia sia il calo troppo rapido della glicemia.",x:2,dead:1,s:{phys:{insulin:1,kshift:0},vit:{ecg:'vf',hr:210}},end:"Aritmia da ipokaliemia"},
   {t:"No: l'insulina si avvia solo quando il K⁺ supera 5,5 mmol/L",fb:"Sopra 5,5 di solito non si aggiunge potassio ai liquidi, ma l'insulina si può avviare già da 3,3. Aspettare 5,5 ritarda inutilmente.",s:{phys:{ketones:.95},vit:{rr:32}},end:"I chetoni salgono"}],
  out:{vit:{hr:104,rr:24,sys:110,dia:66},phys:{glu:300,insulin:.8,ketones:.6,kshift:.3}},
  learn:"Nella chetoacidosi il potassio totale del corpo è basso, anche quando nel sangue sembra normale."},
 {tag:"Rivalutazione",text:"Dopo 6 ore: glicemia 230 mg/dL, chetonemia 2,4 mmol/L, pH 7,26.",
  q:"Cosa ti aspetti come passo successivo?",
  win:"Chetoacidosi risolta",
  opts:[{t:"Si aggiunge una soluzione glucosata all'infusione e si continua l'insulina finché chetoni e pH non tornano nei limiti",ok:1,fb:"L'insulina serve a fermare i chetoni, non solo ad abbassare la glicemia. Il glucosio evita l'ipoglicemia."},
   {t:"Si sospende l'insulina perché la glicemia è quasi a target",fb:"La glicemia sì, ma i chetoni sono ancora alti: senza insulina tornano a salire.",s:{phys:{insulin:0,ketones:.9,glu:260},vit:{rr:30}},end:"I chetoni risalgono"},
   {t:"Si passa subito all'insulina sottocute e si stacca l'infusione",fb:"Il passaggio si fa a chetoacidosi risolta, con la basale sottocute fatta prima di staccare l'infusione.",s:{phys:{insulin:.2,ketones:.8},vit:{rr:28}},end:"I chetoni risalgono"},
   {t:"Si aggiunge bicarbonato perché il pH è ancora sotto 7,30",fb:"Il pH sta migliorando con la terapia: il bicarbonato non è indicato.",s:{phys:{kshift:.1}},end:"Ipokaliemia"}],
  out:{vit:{hr:92,rr:18,sys:114,dia:70},pat:{skin:'normal'},phys:{glu:180,insulin:.8,ketones:.15,kshift:.05}},
  learn:"La chetoacidosi è risolta quando chetoni e pH tornano nei limiti, non quando scende la glicemia."},
 {tag:"Decisione",text:"Giulia sta meglio. Prima della dimissione fai educazione terapeutica con lei e la madre.",
  q:"Quale indicazione per i giorni di malattia è corretta?",
  win:"Giulia sa cosa fare",
  opts:[{t:"Non sospendere mai l'insulina basale, controllare glicemia e chetoni ogni 2-4 ore, bere molto e contattare il centro se vomita o i chetoni superano 1,5 mmol/L",ok:1,fb:"Durante una malattia gli ormoni dello stress alzano la glicemia: l'insulina serve anche se si mangia poco."},
   {t:"Se non mangia, non deve fare insulina, per evitare l'ipoglicemia",fb:"È proprio l'errore che l'ha portata qui.",x:2,s:{phys:{insulin:0,ketones:.9,glu:450},vit:{rr:30}},end:"Nuova chetoacidosi"},
   {t:"Sospendere la basale e fare solo la rapida in base a quello che mangia",fb:"Senza basale l'organismo produce chetoni anche a digiuno.",s:{phys:{insulin:.1,ketones:.6}},end:"Chetoni in salita"},
   {t:"Raddoppiare sempre la basale durante la malattia",fb:"A volte serve più insulina, ma secondo un piano concordato con il diabetologo, non in modo fisso.",s:{phys:{glu:60},pat:{sweat:1}},end:"Ipoglicemia"}],
  learn:"L'educazione terapeutica è uno degli interventi infermieristici con più impatto nel diabete tipo 1."}
 ],
 src:["ADA Consensus Report: Hyperglycemic crises in adult patients with diabetes (2024)","JBDS-IP, The management of diabetic ketoacidosis in adults (2023)"]},

/* ---------------------------------------------------------------- 12 */
{ id:12,diff:'Difficile',title:"Si siede e sviene",area:"Cardiologia",pt:"Sig.ra Rosa C., 82 anni · Medicina interna, letto 15",
 intro:"Mattino, ore 9. La paziente sta meglio e vuole alzarsi.",
 scheda:[["Motivo del ricovero","Edema polmonare acuto ieri sera."],["Terapia di ieri","Furosemide 40 mg EV due volte: diuresi 2000 mL nella notte. Stamattina polmoni liberi."],["Anamnesi","Ipertensione, dislipidemia. Da qualche mese si stanca salendo le scale e una volta ha avuto un capogiro facendo la spesa."],["In cartella","Soffio sistolico, mai approfondito con un ecocardiogramma."],["Terapia al bisogno","Nitroglicerina sublinguale per dolore toracico."],["Prescrizione","Furosemide 40 mg EV anche alle 14."],["Parametri alle 8","PA 110/64 · FC 88 · SpO₂ 95% · FR 18 · T 36,6°C"]],
 base:{vit:{hr:88,sys:110,dia:64,spo2:95,rr:18,temp:36.6,ecg:'sinus'},pat:{pose:0,skin:'normal',eyes:1},phys:{mode:'heart',stenosis:.85,preload:.42,backflow:.1,contract:.8}},
 steps:[
 {tag:"Valutazione",kn:1,text:"Ausculti il cuore con attenzione.",
  q:"Quale soffio ti fa pensare a una stenosi aortica?",
  opts:[{t:"Sistolico eiettivo, rude, al 2° spazio intercostale destro, irradiato alle carotidi",ok:1,fb:"Il focolaio aortico è al 2° spazio destro, e il flusso turbolento risale lungo le carotidi."},
   {t:"Olosistolico all'apice, irradiato all'ascella",fb:"È il soffio dell'insufficienza mitralica."},
   {t:"Diastolico in decrescendo al margine sternale sinistro, meglio udibile con la paziente inclinata in avanti",fb:"È il soffio dell'insufficienza aortica."},
   {t:"Diastolico a rullo all'apice, con schiocco di apertura",fb:"È il quadro della stenosi mitralica."}],
  learn:"Dispnea da sforzo e capogiri sono sintomi tipici della stenosi aortica: andavano approfonditi."},
 {tag:"Decisione",text:"La paziente vuole andare in bagno.",seq:[{d:1.4,cap:"Si mette seduta sul bordo del letto",s:{pat:{pose:2}}},{d:1.6,cap:"Il ventricolo si riempie meno",s:{phys:{preload:.18},vit:{hr:112,sys:84,dia:50}}},{d:1.7,cap:"Perde coscienza",s:{vit:{hr:120,sys:70,dia:42},pat:{collapsed:1,eyes:0,skin:'grey'}}}],
  q:"Perde coscienza da seduta, ha un polso debole e rapido, respira. Cosa fai subito?",
  win:"Si risveglia",
  opts:[{t:"La distendo supina, sollevo le gambe, controllo respiro e polso carotideo, chiamo aiuto e avvio il monitoraggio",ok:1,fb:"Distenderla e sollevare le gambe riporta sangue al cuore: il ventricolo si riempie e la gittata risale."},
   {t:"La sostengo seduta e le do qualche sorso d'acqua zuccherata",fb:"Lo zucchero ha senso in un'ipoglicemia, ma da seduta il cuore resta poco riempito. Ed è incosciente: niente per bocca.",s:{vit:{sys:62,dia:36}},end:"Resta incosciente: PA 62"},
   {t:"Le somministro la nitroglicerina sublinguale prescritta al bisogno, pensando a un'angina",fb:"Nella stenosi aortica l'angina è frequente, ma la nitroglicerina dilata le vene e riduce ancora il precarico. Con una valvola stretta la pressione crolla.",x:2,dead:1,s:{vit:{sys:40,dia:20,hr:130},phys:{preload:.05}},end:"Collasso cardiocircolatorio"},
   {t:"Controllo prima la glicemia capillare, per escludere un'ipoglicemia",fb:"La glicemia si controlla in ogni perdita di coscienza, ma dopo averla distesa: la causa più probabile qui è emodinamica.",s:{vit:{sys:66,dia:38}},end:"Il cervello resta poco perfuso"}],
  out:{pat:{pose:0,collapsed:0,eyes:1,skin:'pale'},phys:{preload:.5},vit:{hr:98,sys:98,dia:58}},
  learn:"Dopo pochi secondi riprende coscienza: il cervello aveva ricevuto troppo poco sangue."},
 {tag:"Decisione",text:"Ore 13:45. PA 98/58, FC 98. Si sente debole. Alle 14 c'è la furosemide 40 mg EV.",
  q:"Cosa fai con la furosemide delle 14?",
  win:"Medico avvisato, diuretico sospeso",
  opts:[{t:"Non la somministro e segnalo subito al medico la sincope, l'ipotensione e il soffio, perché rivaluti la terapia",ok:1,fb:"Un evento nuovo cambia il quadro: serve una rivalutazione medica prima di un altro diuretico."},
   {t:"La somministro: l'edema è stato grave e la terapia è prescritta",fb:"L'edema era reale, ma ora la paziente è asciutta e ipotesa. Un altro diuretico svuota il ventricolo.",x:2,s:{vit:{sys:68,dia:38,hr:124},pat:{collapsed:1,eyes:0,skin:'grey'},phys:{preload:.12}},end:"Nuova sincope"},
   {t:"Dimezzo la dose di mia iniziativa, per prudenza",fb:"La dose la decide il medico. Anche metà dose riduce il precarico.",s:{vit:{sys:84,dia:50},phys:{preload:.3}},end:"PA 84/50"},
   {t:"La somministro e preparo in parallelo un bolo di fisiologica",fb:"Togliere e dare liquidi insieme non ha senso: serve una decisione medica chiara.",s:{vit:{sys:86}},end:"Terapia contraddittoria"}],
  learn:"La furosemide era giusta per l'edema. Togliere molto liquido senza conoscere la valvola no: se c'è un soffio, prima si capisce qual è la valvola."},
 {tag:"Fisiologia",fis:1,kn:1,text:"Guarda il ventricolo e il loop pressione-volume nella lente.",
  q:"Perché in questa paziente la gittata dipende così tanto dal riempimento?",
  opts:[{t:"La valvola stretta è un ostacolo fisso all'uscita e il ventricolo ispessito è rigido: con poco riempimento non può aumentare la gittata",ok:1,fb:"Un cuore normale compensa un calo di precarico. Qui no."},
   {t:"La valvola non si chiude bene e il sangue torna indietro nel ventricolo",fb:"È il meccanismo dell'insufficienza aortica."},
   {t:"Il ventricolo è dilatato e la frazione d'eiezione è ridotta",fb:"È il quadro di una cardiomiopatia dilatativa. Qui la frazione d'eiezione è conservata."},
   {t:"L'atrio destro non si contrae per la fibrillazione atriale",fb:"La perdita della contrazione atriale peggiora la stenosi aortica, ma la paziente è in ritmo sinusale."}],
  learn:"Nel loop pressione-volume il picco di pressione ventricolare supera di molto quella aortica: è il gradiente attraverso la valvola."},
 {tag:"Decisione",text:"L'ecocardiogramma conferma una stenosi aortica severa.",physMode:{mode:'heart',stenosis:.05,preload:.55,backflow:0,contract:.8},
  q:"Quale elemento rende indicata la sostituzione della valvola?",
  win:"Valvola sostituita",
  kn:1,
  opts:[{t:"La presenza di sintomi (sincope, dispnea da sforzo, angina) in una stenosi severa",ok:1,fb:"Una volta comparsi i sintomi, la prognosi senza intervento peggiora molto."},
   {t:"Un soffio molto intenso, anche senza sintomi",fb:"L'intensità del soffio non dice quanto è grave la stenosi: quando la gittata cala, il soffio può addirittura attenuarsi."},
   {t:"Palpitazioni occasionali",fb:"Non sono il criterio che guida l'indicazione."},
   {t:"Edema malleolare serale",fb:"È poco specifico."}],
  learn:"La sostituzione, percutanea (TAVI) o chirurgica, viene decisa dall'Heart Team. Nell'animazione la valvola è stata sostituita e il gradiente scompare."}
 ],
 src:["2025 ESC/EACTS Guidelines for the management of valvular heart disease","Caso ispirato a un reel didattico del Dr. Reza Shahnazar (@rezashahnazar), rielaborato"]}
];
